/* Déclic — parcours de mathématiques.
   Chaque cours : id, br (alg | ana | geo), lv (ecole | gym | uni), h, p, lessons (titres), steps (1re leçon jouable).
   Types d'étapes (déduits des champs) :
   - params + draw [+ info]        → exploration avec curseurs
   - params + draw + ok + why      → pratique : régler les curseurs pour atteindre un but
   - opts + ans + why              → QCM
   - ans + why (sans opts)         → réponse numérique (virgule, fraction acceptées), tol optionnelle */


function fracBar(n,d,col='var(--math)'){
  const W=300,h=38,bars=Math.max(1,Math.ceil(n/d)),w=(W-4)/d; let s='';
  for(let b=0;b<bars;b++) for(let i=0;i<d;i++){ const k=b*d+i;
    s+=`<rect x="${2+i*w}" y="${2+b*(h+8)}" width="${w}" height="${h}" fill="${k<n?col:'var(--surface)'}" stroke="var(--ink)" stroke-width="1.5"/>`; }
  return `<svg viewBox="0 0 ${W} ${bars*(h+8)}" width="${W}">${s}</svg>`;
}
function balance(L,R){
  const items=(cx,o)=>{ const arr=[...Array(o.x).fill('x'),...Array(o.u).fill('u')]; return arr.map((t,i)=>{
    const x=cx-57+(i%5)*23, y=124-Math.floor(i/5)*24;
    return t==='x'?`<rect x="${x}" y="${y-22}" width="21" height="21" rx="4" fill="var(--accent)"/><text x="${x+10.5}" y="${y-6}" font-size="13" font-weight="700" text-anchor="middle" fill="var(--accent-ink)">x</text>`
                  :`<circle cx="${x+10.5}" cy="${y-10}" r="9" fill="var(--spark)"/>`; }).join(''); };
  const pan=cx=>`<line x1="${cx-58}" y1="128" x2="${cx}" y2="30" stroke="var(--muted)"/><line x1="${cx+58}" y1="128" x2="${cx}" y2="30" stroke="var(--muted)"/><rect x="${cx-60}" y="126" width="120" height="6" rx="3" fill="var(--ink)"/>`;
  return `<svg viewBox="0 0 320 175" width="320"><path d="M160 30 L146 172 H174Z" fill="var(--muted)"/>${pan(90)}${pan(230)}<line x1="30" y1="30" x2="290" y2="30" stroke="var(--ink)" stroke-width="4" stroke-linecap="round"/><circle cx="160" cy="30" r="6" fill="var(--ink)"/>${items(90,L)}${items(230,R)}</svg>`;
}
const LEVELS={ecole:{h:'École obligatoire',s:'9e – 11e année'},gym:{h:'Gymnase',s:'Maturité'},uni:{h:'Université',s:'1re année'}};
const BRANCHES={alg:'Algèbre',ana:'Analyse',geo:'Géométrie'};

const MATHS=[
/* ================= ÉCOLE OBLIGATOIRE ================= */
{id:'fractions',br:'alg',lv:'ecole',h:'Fractions',p:'Partager, comparer et calculer avec des parts.',
 lessons:['Fractions équivalentes','Additionner des fractions','Multiplier et diviser','Fractions et nombres décimaux'],
 steps:[
  {h:'Une fraction, c’est un partage',p:`Le <b>dénominateur</b> (en bas) dit en combien de parts égales on coupe. Le <b>numérateur</b> (en haut) dit combien de parts on prend.`,
   params:[{id:'n',l:'Numérateur',min:0,max:12,v:3},{id:'d',l:'Dénominateur',min:1,max:12,v:4}],
   draw:v=>fracBar(v.n,v.d), info:v=>`${F(v.n,v.d)} = ${fmt(v.n/v.d,3)}${v.n>v.d?' : plus d’une barre entière':''}`},
  {h:'Même part, autre écriture',p:`Quelle fraction vaut autant que ${F(2,3)}&nbsp;?`,fig:fracBar(2,3)+fracBar(4,6),
   opts:[F(4,6),F(3,4),F(2,6),F(6,4)],ans:0,why:`Multiplier le haut et le bas par 2 ne change pas la part : ${F(2,3)} = ${F(4,6)}. Les deux barres ont la même longueur colorée.`},
  {h:'Colorie trois quarts',p:`La barre est coupée en 8. Combien de huitièmes faut-il colorier pour obtenir ${F(3,4)}&nbsp;?`,
   params:[{id:'n',l:'Parts coloriées',min:0,max:8,v:1}],draw:v=>fracBar(v.n,8)+fracBar(3,4,'var(--line)'),
   ok:v=>v.n===6,why:`${F(3,4)} = ${F(6,8)} : on multiplie haut et bas par 2.`},
  {kind:'Défi',h:'Additionne',p:`${F(1,2)} + ${F(1,3)} = ${F('?',6)}. Quel est le numérateur&nbsp;?`,fig:fracBar(3,6)+fracBar(2,6,'var(--spark)'),
   ans:5,why:`On met tout en sixièmes : ${F(1,2)} = ${F(3,6)} et ${F(1,3)} = ${F(2,6)}. Donc ${F(3,6)} + ${F(2,6)} = ${F(5,6)}.`},
  {kind:'Problème',h:'La recette pour quatre',
   p:`Une recette de gâteau pour 6 personnes demande ${F(3,4)} de litre de lait et ${F(2,3)} de tasse de sucre. Ce soir, vous n’êtes que 4. Tu veux garder exactement le même goût, donc réduire chaque ingrédient dans la même proportion.`,
   fig:fracBar(3,4)+fracBar(2,3,'var(--spark)'),
   parts:[
    {q:'a) Quelle fraction de la recette prépares-tu ?',opts:[F(3,2),F(2,3),F(1,2),F(4,10)],ans:1,hint:'Tu cuisines pour 4 personnes au lieu de 6.',why:`${F(4,6)} = ${F(2,3)} : tu prépares les deux tiers de la recette.`},
    {q:'b) Combien de litres de lait faut-il ?',unit:'L',ans:.5,tol:.001,hint:`Prendre ${F(2,3)} d’une quantité, c’est la multiplier par ${F(2,3)}.`,why:`${F(3,4)} × ${F(2,3)} = ${F(6,12)} = ${F(1,2)} L.`},
    {q:'c) Quelle fraction de tasse de sucre faut-il ? (fraction)',unit:'tasse',ans:4/9,tol:.003,hint:'Multiplie les numérateurs entre eux et les dénominateurs entre eux.',why:`${F(2,3)} × ${F(2,3)} = ${F(4,9)} de tasse, un peu moins d’une demi-tasse.`},
   ],
   sol:`On passe de 6 à 4 personnes : on prend ${F(4,6)} = ${F(2,3)} de chaque quantité.<br>Lait : ${F(3,4)} × ${F(2,3)} = ${F(6,12)} = ${F(1,2)} L.<br>Sucre : ${F(2,3)} × ${F(2,3)} = ${F(4,9)} de tasse.<br>Prendre une fraction d’une quantité revient toujours à multiplier par cette fraction.`},
  {kind:'Problème',h:'Le partage de la pizza',
   p:`Trois amis partagent une pizza de 480 g. Ana en mange ${F(1,3)}. Ben en mange ${F(3,8)}. Chloé mange ensuite la moitié de ce qui reste. On cherche ce qui reste à la fin et qui a mangé le plus.`,
   parts:[
    {q:'a) Ana et Ben ont mangé ensemble une fraction de dénominateur 24. Quel est son numérateur ?',lab:'?/24 :',ans:17,hint:'Écris les deux fractions en vingt-quatrièmes.',why:`${F(1,3)} = ${F(8,24)} et ${F(3,8)} = ${F(9,24)}, donc ${F(17,24)}.`},
    {q:'b) Chloé mange une fraction de la pizza entière de dénominateur 48. Quel est son numérateur ?',lab:'?/48 :',ans:7,hint:'Il reste d’abord 1 − 17/24. Chloé en prend la moitié.',why:`Il reste ${F(7,24)}. La moitié de ${F(7,24)} est ${F(7,48)}.`},
    {q:'c) Combien de grammes de pizza reste-t-il à la fin ?',unit:'g',ans:70,hint:'Après Chloé, il reste la même quantité que ce qu’elle a mangé.',why:`Il reste ${F(7,48)} de la pizza : 480 × ${F(7,48)} = 70 g.`},
    {q:'d) Qui a mangé le plus ?',opts:['Ana','Ben','Chloé','Ana et Ben autant'],ans:1,hint:'Compare les trois fractions avec le dénominateur 48.',why:`Ana : ${F(16,48)}, Ben : ${F(18,48)}, Chloé : ${F(7,48)}. Ben a mangé le plus.`},
   ],
   sol:`Ana et Ben : ${F(1,3)} + ${F(3,8)} = ${F(8,24)} + ${F(9,24)} = ${F(17,24)}.<br>Reste : 1 − ${F(17,24)} = ${F(7,24)}. Chloé en mange la moitié, soit ${F(7,48)} de la pizza.<br>Il reste ${F(7,48)}, soit 480 × 7 ÷ 48 = 70 g.<br>En quarante-huitièmes : Ana 16, Ben 18, Chloé 7. Ben a mangé le plus, avec 180 g.`},
 ]},

{id:'litteral',br:'alg',lv:'ecole',h:'Calcul littéral',p:'Développer, factoriser, et voir les formules comme des aires.',
 lessons:['Développer avec des rectangles','Factoriser','Identités remarquables','Réduire une expression'],
 steps:[
  {h:'Développer, c’est découper un rectangle',p:`Un rectangle de largeur <i>a</i> et de longueur <i>b + c</i> a une aire <i>a(b + c)</i>. Coupé en deux, il donne <i>ab + ac</i>.`,
   params:[{id:'a',l:'a',min:1,max:4,v:2},{id:'b',l:'b',min:1,max:5,v:3},{id:'c',l:'c',min:1,max:4,v:2}],
   draw:v=>{ const P=plane({x:[-0.5,9.5],y:[-0.8,4.8],grid:false,axes:false});
     P.rect(0,0,v.b,v.a,{fill:'var(--math)',fo:.3,c:'var(--ink)',w:2}).rect(v.b,0,v.c,v.a,{fill:'var(--spark)',fo:.45,c:'var(--ink)',w:2});
     P.text(v.b/2,v.a/2,'ab',{a:'middle',dy:5,s:16}).text(v.b+v.c/2,v.a/2,'ac',{a:'middle',dy:5,s:16});
     P.text(v.b/2,0,'b',{a:'middle',dy:18}).text(v.b+v.c/2,0,'c',{a:'middle',dy:18}).text(0,v.a/2,'a',{a:'end',dx:-6,dy:5}); return P.svg(); },
   info:v=>`${v.a}(${v.b} + ${v.c}) = ${v.a*v.b} + ${v.a*v.c} = ${v.a*(v.b+v.c)}`},
  {h:'À toi',p:'Développe <i>3(x + 4)</i>.',opts:['3x + 4','3x + 12','3x + 7','x + 12'],ans:1,why:'Le 3 multiplie chaque terme de la parenthèse : 3·x + 3·4 = 3x + 12.'},
  {h:'(a + b)², un carré en quatre morceaux',p:'Un carré de côté <i>a + b</i> se découpe en un carré <i>a²</i>, un carré <i>b²</i> et deux rectangles <i>ab</i>.',
   params:[{id:'a',l:'a',min:1,max:4,v:3},{id:'b',l:'b',min:1,max:3,v:2}],
   draw:v=>{ const s=v.a+v.b,P=plane({x:[-0.8,7.3],y:[-0.8,7.3],grid:false,axes:false});
     P.rect(0,v.b,v.a,v.a,{fill:'var(--math)',fo:.35,c:'var(--ink)',w:2}).rect(v.a,0,v.b,v.b,{fill:'var(--spark)',fo:.5,c:'var(--ink)',w:2})
      .rect(0,0,v.a,v.b,{fill:'var(--accent)',fo:.2,c:'var(--ink)',w:2}).rect(v.a,v.b,v.b,v.a,{fill:'var(--accent)',fo:.2,c:'var(--ink)',w:2});
     P.text(v.a/2,v.b+v.a/2,'a²',{a:'middle',dy:5,s:16}).text(v.a+v.b/2,v.b/2,'b²',{a:'middle',dy:5,s:15}).text(v.a/2,v.b/2,'ab',{a:'middle',dy:5}).text(v.a+v.b/2,v.b+v.a/2,'ab',{a:'middle',dy:5});
     return P.svg(); },
   info:v=>`(${v.a} + ${v.b})² = ${v.a*v.a} + 2·${v.a*v.b} + ${v.b*v.b} = ${(v.a+v.b)**2}`,
   note:'<b>Erreur fréquente :</b> (a + b)² n’est pas a² + b². Il manque les deux rectangles ab.'},
  {kind:'Défi',h:'Identité remarquable',p:'Développe <i>(x + 5)²</i>.',opts:['x² + 25','x² + 10x + 25','x² + 5x + 25','2x + 10'],ans:1,why:'(x + 5)² = x² + 2·5·x + 5² = x² + 10x + 25.'},
  {kind:'Problème',h:'Le plan de la chambre',
   p:'Sur le plan d’une chambre rectangulaire, la largeur vaut <i>x</i> mètres et la longueur vaut 3 m de plus. Tu veux écrire l’aire et le périmètre en fonction de <i>x</i>, puis retrouver les dimensions à partir d’une mesure.',
   fig:(()=>{ const P=plane({x:[-1.5,8.5],y:[-1.2,5],grid:false,axes:false}); P.rect(0,0,7,4,{fill:'var(--math)',fo:.2,c:'var(--ink)',w:2}).text(3.5,0,'x + 3',{a:'middle',dy:18}).text(0,2,'x',{a:'end',dx:-8,dy:5}); return P.svg(); })(),
   parts:[
    {q:'a) Quelle expression donne l’aire de la chambre ?',opts:['x² + 3','2x + 3','x² + 3x','x² + 3x + 3'],ans:2,hint:'Aire = largeur × longueur, puis développe.',why:'x(x + 3) = x² + 3x.'},
    {q:'b) Quelle est l’aire si x = 4 ?',unit:'m²',ans:28,hint:'Remplace x par 4 dans ton expression.',why:'4² + 3·4 = 16 + 12 = 28 m² (ou 4 × 7).'},
    {q:'c) Quelle expression réduite donne le périmètre ?',opts:['4x + 6','2x + 6','4x + 3','x² + 6'],ans:0,hint:'Périmètre = 2 × largeur + 2 × longueur.',why:'2x + 2(x + 3) = 2x + 2x + 6 = 4x + 6.'},
    {q:'d) Le périmètre mesure 30 m. Quelle est la largeur ?',lab:'x =',unit:'m',ans:6,hint:'Résous 4x + 6 = 30.',why:'4x = 24, donc x = 6 m. La chambre fait 6 m sur 9 m.'},
   ],
   sol:'Aire : A = x(x + 3) = x² + 3x. Pour x = 4 : 28 m².<br>Périmètre : P = 2x + 2(x + 3) = 4x + 6.<br>Si P = 30 : 4x = 24 et x = 6. La chambre mesure 6 m sur 9 m, pour une aire de 54 m².'},
  {kind:'Problème',h:'Agrandir le jardin',
   p:'Un jardin carré a un côté de <i>x</i> mètres. On l’agrandit en ajoutant une bande de 2 m sur deux côtés : le nouveau jardin est un carré de côté <i>x + 2</i>. L’aire gagne ainsi 36 m². Quel était le côté du jardin de départ&nbsp;?',
   fig:(()=>{ const P=plane({x:[-1,8],y:[-1,8],grid:false,axes:false,w:260}); P.rect(0,0,7,7,{fill:'var(--spark)',fo:.4,c:'var(--ink)',w:2}).rect(0,0,5,5,{fill:'var(--math)',fo:.35,c:'var(--ink)',w:2}).text(2.5,2.5,'x²',{a:'middle',dy:5,s:16}).text(2.5,0,'x',{a:'middle',dy:16}).text(6,0,'2',{a:'middle',dy:16}); return P.svg(); })(),
   parts:[
    {q:'a) Développe (x + 2)².',opts:['x² + 4','x² + 4x + 4','x² + 2x + 4','x² + 4x + 2'],ans:1,hint:'(a + b)² = a² + 2ab + b².',why:'(x + 2)² = x² + 2·2·x + 2² = x² + 4x + 4.'},
    {q:'b) Que vaut l’aire gagnée (x + 2)² − x² une fois réduite ?',opts:['4','4x + 4','2x + 4','4x² + 4'],ans:1,hint:'Les x² s’annulent.',why:'x² + 4x + 4 − x² = 4x + 4. Sur la figure : deux bandes 2 × x et un carré 2 × 2.'},
    {q:'c) Quel était le côté du jardin de départ ?',lab:'x =',unit:'m',ans:8,hint:'Résous 4x + 4 = 36.',why:'4x = 32, donc x = 8 m.'},
    {q:'d) Quelle est l’aire du nouveau jardin ?',unit:'m²',ans:100,hint:'Le nouveau côté vaut x + 2.',why:'10² = 100 m². Contrôle : 100 − 64 = 36 m².'},
   ],
   sol:'L’aire gagnée vaut (x + 2)² − x² = x² + 4x + 4 − x² = 4x + 4.<br>On résout 4x + 4 = 36, d’où 4x = 32 et x = 8 m.<br>Le nouveau jardin mesure 10 m de côté, soit 100 m².<br>Contrôle : 100 − 64 = 36 m². Le piège serait d’écrire (x + 2)² = x² + 4, qui oublie les deux bandes.'},
 ]},

{id:'equations1',br:'alg',lv:'ecole',h:'Équations du 1er degré',p:'Trouver l’inconnue en gardant la balance en équilibre.',
 lessons:['La balance','Équations avec parenthèses','Mettre un problème en équation','Inéquations'],
 steps:[
  {h:'Une équation est une balance',p:'Les deux côtés pèsent pareil. On peut faire la même opération des deux côtés sans la déséquilibrer. Avance étape par étape.',
   params:[{id:'e',l:'Étape',min:0,max:2,v:0}],
   draw:v=>[balance({x:3,u:2},{x:0,u:11}),balance({x:3,u:0},{x:0,u:9}),balance({x:1,u:0},{x:0,u:3})][v.e],
   info:v=>['<b>3x + 2 = 11</b>','On enlève 2 de chaque côté : <b>3x = 9</b>','On divise chaque côté par 3 : <b>x = 3</b>'][v.e]},
  {h:'À toi',p:'<i>5x − 7 = 18</i>. Combien vaut <i>x</i>&nbsp;?',lab:'x =',ans:5,why:'On ajoute 7 : 5x = 25. On divise par 5 : x = 5.'},
  {h:'Par où commencer&nbsp;?',p:'<i>4x + 3 = 2x + 11</i>. Quelle est une bonne première étape&nbsp;?',
   opts:['Soustraire 2x des deux côtés','Diviser seulement le côté gauche par 4','Ajouter 3 des deux côtés','Multiplier 2x par 11'],ans:0,
   why:'On regroupe les x d’un seul côté : 2x + 3 = 11, puis 2x = 8, donc x = 4.'},
  {kind:'Défi',h:'Mettre en équation',p:'Léa a trois fois l’âge de son frère. Ensemble, ils ont 48 ans. Quel âge a son frère&nbsp;?',unit:'ans',ans:12,
   why:'Frère : x. Léa : 3x. Donc x + 3x = 48, 4x = 48 et x = 12.'},
  {kind:'Problème',h:'Avec ou sans carte',
   p:'Au cinéma, un billet coûte 15 CHF. Avec la carte annuelle, qui coûte 30 CHF, chaque billet ne coûte plus que 10 CHF. On note <i>x</i> le nombre de films vus dans l’année. À partir de combien de films la carte vaut-elle la peine&nbsp;?',
   parts:[
    {q:'a) Combien paie-t-on pour 4 films avec la carte ?',unit:'CHF',ans:70,hint:'Prix de la carte + prix des billets.',why:'30 + 4 × 10 = 70 CHF (contre 60 CHF sans carte).'},
    {q:'b) Pour combien de films les deux formules coûtent-elles la même chose ?',lab:'x =',ans:6,hint:'Résous 15x = 30 + 10x.',why:'15x − 10x = 30, donc 5x = 30 et x = 6.'},
    {q:'c) Pour 10 films, combien économise-t-on avec la carte ?',unit:'CHF',ans:20,hint:'Calcule les deux prix et fais la différence.',why:'Sans carte : 150 CHF. Avec carte : 30 + 100 = 130 CHF. On économise 20 CHF.'},
    {q:'d) À partir de combien de films la carte est-elle strictement plus avantageuse ?',ans:7,hint:'Il faut 30 + 10x < 15x, avec x entier.',why:'30 < 5x donne x > 6. Le premier entier est 7.'},
   ],
   sol:'Sans carte : 15x. Avec carte : 30 + 10x.<br>Égalité : 15x = 30 + 10x, donc 5x = 30 et x = 6 films.<br>La carte est plus avantageuse si 30 + 10x < 15x, soit x > 6.<br>Dès 7 films, la carte fait gagner de l’argent : 5 CHF de plus par film au-delà de 6.'},
  {kind:'Problème',h:'Le triple de son âge',
   p:'Un père a 41 ans et sa fille 9 ans. On se demande dans combien d’années le père aura exactement le triple de l’âge de sa fille. Puis on remonte le temps : il y a combien d’années avait-il cinq fois son âge&nbsp;?',
   parts:[
    {q:'a) On note t le nombre d’années à attendre. Quelle équation traduit le problème ?',opts:['41 + t = 3·9 + t','3(41 + t) = 9 + t','41 + t = 3(9 + t)','41 = 3(9 + t)'],ans:2,hint:'Les deux vieillissent de t années.',why:'Dans t ans, le père a 41 + t ans et sa fille 9 + t. Le père doit avoir le triple : 41 + t = 3(9 + t).'},
    {q:'b) Résous l’équation.',lab:'t =',unit:'ans',ans:7,hint:'Développe 3(9 + t), puis regroupe les t d’un côté.',why:'41 + t = 27 + 3t, donc 14 = 2t et t = 7.'},
    {q:'c) Quel âge aura le père à ce moment-là ?',unit:'ans',ans:48,hint:'Ajoute t à 41.',why:'41 + 7 = 48 ans, et sa fille aura 16 ans : 3 × 16 = 48.'},
    {q:'d) Il y a combien d’années le père avait-il exactement 5 fois l’âge de sa fille ?',unit:'an(s)',ans:1,hint:'Il y a s années : 41 − s = 5(9 − s).',why:'41 − s = 45 − 5s, donc 4s = 4 et s = 1. Il y a un an : 40 = 5 × 8.'},
   ],
   sol:'Dans t ans : 41 + t = 3(9 + t), soit 41 + t = 27 + 3t, donc t = 7. Le père aura 48 ans et sa fille 16.<br>Il y a s ans : 41 − s = 5(9 − s), soit 41 − s = 45 − 5s, donc 4s = 4 et s = 1.<br>Contrôle : l’an dernier, le père avait 40 ans et sa fille 8.<br>Point clé : les deux personnes vieillissent du même nombre d’années, d’où la parenthèse.'},
 ]},

{id:'proportion',br:'ana',lv:'ecole',h:'Proportionnalité et pourcentages',p:'Règle de trois, pourcentages, TVA et soldes.',
 lessons:['Grandeurs proportionnelles','Pourcentages','Hausses et baisses successives','Échelles et vitesses'],
 steps:[
  {h:'Proportionnel = droite qui passe par 0',p:'Si 1 kg de pommes coûte <i>p</i> francs, <i>x</i> kg coûtent <i>p·x</i>. Le graphe est une droite qui part de l’origine.',
   params:[{id:'p',l:'Prix au kilo',min:1,max:6,step:.5,v:2.5,u:' CHF'}],
   draw:v=>{ const P=plane({x:[-0.4,5.5],y:[-2,32],h:260,step:1,grid:false,lx:1,ly:10});
     for(let y=0;y<=30;y+=10) P.seg(0,y,5.5,y,{c:'var(--line)',w:1}); P.fn(x=>v.p*x,{from:0});
     [1,2,3,4,5].forEach(x=>P.dot(x,v.p*x,{r:5})); P.text(5.4,0,'kg',{a:'end',dy:-6,c:'var(--muted)'}); return P.svg(); },
   info:v=>`1 kg → ${fmt(v.p)} CHF · 2 kg → ${fmt(2*v.p)} CHF · 4 kg → ${fmt(4*v.p)} CHF`},
  {h:'Règle de trois',p:'3 kg de pommes coûtent 7,50 CHF. Combien coûtent 5 kg&nbsp;?',unit:'CHF',ans:12.5,tol:.001,why:'Prix au kilo : 7,50 ÷ 3 = 2,50 CHF. Pour 5 kg : 5 × 2,50 = 12,50 CHF.'},
  {h:'Le piège des pourcentages',p:'Un prix augmente de 20 %, puis baisse de 20 %. Au final&nbsp;?',
   opts:['Il revient au prix de départ','Il a baissé de 4 %','Il a monté de 4 %','Il a baissé de 2 %'],ans:1,
   why:'×1,2 puis ×0,8 donne ×0,96. La baisse s’applique à un montant plus grand, donc on perd 4 %.'},
  {kind:'Défi',h:'La TVA',p:'Une facture fait 200 CHF hors taxe. Avec la TVA suisse de 8,1 %, combien paie-t-on&nbsp;?',unit:'CHF',ans:216.2,tol:.001,why:'200 × 1,081 = 216,20 CHF.'},
  {kind:'Problème',h:'Soldes et carte fidélité',
   p:'Une veste coûte 180 CHF. Pendant les soldes, elle est à −30 %. À la caisse, ta carte fidélité donne encore −10 % sur le prix soldé. Le vendeur affirme que tu as eu « 40 % de rabais ». Vérifie.',
   parts:[
    {q:'a) Quel est le prix soldé ?',unit:'CHF',ans:126,tol:.001,hint:'Baisser de 30 %, c’est multiplier par 0,7.',why:'180 × 0,7 = 126 CHF.'},
    {q:'b) Combien paies-tu à la caisse ?',unit:'CHF',ans:113.4,tol:.001,hint:'La 2e baisse porte sur 126 CHF.',why:'126 × 0,9 = 113,40 CHF.'},
    {q:'c) Quel est le pourcentage total de réduction ?',unit:'%',ans:37,tol:.001,hint:'Le coefficient total est 0,7 × 0,9.',why:'0,7 × 0,9 = 0,63. Tu paies 63 % du prix, donc la réduction totale est de 37 %.'},
    {q:'d) Le vendeur a-t-il raison ?',opts:['Oui, 30 % + 10 % = 40 %','Non, les 10 % portent sur un prix déjà réduit','Non, la réduction totale dépasse 40 %','Oui, si on paie comptant'],ans:1,hint:'Compare 40 % de 180 et la réduction réelle.',why:'Les 10 % sont pris sur 126 CHF, pas sur 180 CHF. On ne peut pas additionner des pourcentages successifs.'},
   ],
   sol:'Prix soldé : 180 × 0,7 = 126 CHF.<br>Prix final : 126 × 0,9 = 113,40 CHF.<br>Coefficient global : 0,7 × 0,9 = 0,63, soit une réduction de 37 % (66,60 CHF).<br>Avec −40 %, la veste coûterait 108 CHF. Les pourcentages successifs se multiplient, ils ne s’additionnent pas.'},
  {kind:'Problème',h:'La randonnée sur la carte',
   p:'Sur une carte au 1:50 000, le sentier d’une randonnée mesure 18 cm. Tu marches à 4,5 km/h en moyenne et tu prévois une pause de 20 minutes. Un ami a une autre carte où le même sentier mesure 36 cm.',
   parts:[
    {q:'a) Quelle est la longueur réelle du sentier ?',unit:'km',ans:9,tol:.001,hint:'1 cm sur la carte vaut 50 000 cm en vrai. 1 km = 100 000 cm.',why:'18 × 50 000 = 900 000 cm = 9 km.'},
    {q:'b) Combien d’heures marches-tu ?',unit:'h',ans:2,tol:.001,hint:'Durée = distance ÷ vitesse.',why:'9 ÷ 4,5 = 2 h.'},
    {q:'c) Combien de minutes dure la sortie, pause comprise ?',unit:'min',ans:140,hint:'Convertis les heures en minutes.',why:'2 h = 120 min, plus 20 min de pause : 140 min. Parti à 9 h 15, tu arrives à 11 h 35.'},
    {q:'d) Quelle est l’échelle de la carte de ton ami ? (1 : ?)',lab:'1 :',ans:25000,hint:'36 cm représentent les mêmes 900 000 cm.',why:'900 000 ÷ 36 = 25 000. C’est une carte au 1:25 000, deux fois plus détaillée.'},
   ],
   sol:'Distance réelle : 18 × 50 000 = 900 000 cm = 9 km.<br>Marche : 9 ÷ 4,5 = 2 h, soit 120 min, plus 20 min de pause : 140 min au total.<br>Autre carte : 900 000 ÷ 36 = 25 000, donc 1:25 000.<br>La longueur sur la carte double quand le dénominateur de l’échelle est divisé par 2 : les deux grandeurs sont inversement proportionnelles.'},
 ]},

{id:'affines',br:'ana',lv:'ecole',use:'pente',h:'Fonctions affines',p:'Pentes, droites et tout ce qui monte ou descend.',
 lessons:['La pente d’une droite','Ordonnée à l’origine','Droite passant par deux points','Comparer des tarifs']},

{id:'pythagore',br:'geo',lv:'ecole',h:'Théorème de Pythagore',p:'Le plus célèbre des théorèmes, vu avec des carrés.',
 lessons:['Le théorème en images','La réciproque','Distances dans un repère','Pythagore dans l’espace'],
 steps:[
  {h:'a² + b² = c²',p:'Dans un triangle rectangle, l’aire du carré construit sur l’hypoténuse égale la somme des aires des deux autres carrés.',
   params:[{id:'a',l:'Côté a',min:1,max:5,v:3},{id:'b',l:'Côté b',min:1,max:5,v:4}],
   draw:v=>{ const a=v.a,b=v.b,P=plane({x:[-5.5,10.5],y:[-5.5,10.5],grid:false,axes:false,w:300});
     P.poly([[0,0],[a,0],[a,-a],[0,-a]],{fill:'var(--math)',fo:.35,c:'var(--ink)',w:1.5})
      .poly([[0,0],[0,b],[-b,b],[-b,0]],{fill:'var(--spark)',fo:.45,c:'var(--ink)',w:1.5})
      .poly([[a,0],[0,b],[b,a+b],[a+b,a]],{fill:'var(--accent)',fo:.3,c:'var(--ink)',w:1.5})
      .poly([[0,0],[a,0],[0,b]],{fill:'var(--surface)',fo:1,c:'var(--ink)',w:2.5});
     P.text(a/2,-a/2,`${a*a}`,{a:'middle',dy:5,s:15}).text(-b/2,b/2,`${b*b}`,{a:'middle',dy:5,s:15}).text((a+b)/2,(a+b)/2,`${a*a+b*b}`,{a:'middle',dy:5,s:16});
     return P.svg(); },
   info:v=>`${v.a}² + ${v.b}² = ${v.a*v.a} + ${v.b*v.b} = ${v.a*v.a+v.b*v.b}, donc c = ${fmt(Math.hypot(v.a,v.b))}`},
  {h:'Calcule l’hypoténuse',p:'Les côtés de l’angle droit mesurent 6 cm et 8 cm. Quelle est la longueur de l’hypoténuse&nbsp;?',unit:'cm',ans:10,why:'6² + 8² = 36 + 64 = 100, et √100 = 10.'},
  {h:'L’échelle contre le mur',p:'Une échelle de 5 m est posée contre un mur. Son pied est à 3 m du mur. À quelle hauteur touche-t-elle le mur&nbsp;?',
   fig:(()=>{ const P=plane({x:[-0.5,4.5],y:[-0.5,5],grid:false,axes:false,w:240}); P.seg(0,0,4.2,0,{c:'var(--muted)',w:3}).seg(0,0,0,4.8,{c:'var(--muted)',w:6}).seg(3,0,0,4,{c:'var(--spark)',w:5})
     .text(1.5,0,'3 m',{a:'middle',dy:18}).text(1.6,2.2,'5 m',{s:14}).text(0,2,'?',{dx:-14,s:16}); return P.svg(); })(),
   unit:'m',ans:4,why:'h² + 3² = 5², donc h² = 25 − 9 = 16 et h = 4 m.'},
  {kind:'Défi',h:'La réciproque',p:'Un triangle a des côtés de 5, 12 et 13 cm. Est-il rectangle&nbsp;?',opts:['Oui','Non','On ne peut pas savoir sans mesurer un angle'],ans:0,
   why:'5² + 12² = 25 + 144 = 169 = 13². La réciproque de Pythagore dit qu’il est rectangle.'},
  {kind:'Problème',h:'La tringle dans la chambre',
   p:'Une chambre a la forme d’un pavé : 4 m de long, 3 m de large et 2,4 m de haut. Tu dois y ranger une tringle rigide de 5,3 m. Rentre-t-elle, et comment&nbsp;?',
   parts:[
    {q:'a) Quelle est la longueur de la diagonale du sol ?',unit:'m',ans:5,tol:.001,hint:'Le sol est un rectangle 4 × 3.',why:'√(4² + 3²) = √25 = 5 m.'},
    {q:'b) Quelle est la longueur de la grande diagonale, d’un coin du sol au coin opposé du plafond ? (au centième)',unit:'m',ans:5.55,tol:.011,hint:'Triangle rectangle : la diagonale du sol, la hauteur, et la grande diagonale comme hypoténuse.',why:'√(5² + 2,4²) = √30,76 ≈ 5,55 m.'},
    {q:'c) La tringle de 5,3 m entre-t-elle ?',opts:['Oui, posée en diagonale sur le sol','Oui, mais seulement en diagonale de l’espace','Non, elle est trop longue','Oui, le long d’un mur'],ans:1,hint:'Compare 5,3 avec les deux diagonales.',why:'5,3 > 5 : elle ne tient pas à plat. Mais 5,3 < 5,55 : elle tient en biais, du sol au plafond.'},
   ],
   sol:'Diagonale du sol : √(4² + 3²) = 5 m.<br>Grande diagonale : on applique Pythagore dans le triangle formé par la diagonale du sol (5 m) et la hauteur (2,4 m) : √(25 + 5,76) = √30,76 ≈ 5,55 m.<br>La tringle (5,3 m) est trop longue pour le sol, mais plus courte que la grande diagonale : elle rentre en biais.'},
  {kind:'Problème',h:'Trois arbres dans le jardin',
   p:'Sur un plan quadrillé en mètres, trois arbres sont placés en A(1 ; 1), B(7 ; 3) et C(5 ; 9). Le jardinier pense que l’angle en B est droit. On veut le vérifier sans rapporteur, puis calculer l’aire du triangle.',
   fig:(()=>{ const P=plane({x:[-0.5,10],y:[-0.5,10],w:280,lab:2}); P.poly([[1,1],[7,3],[5,9]],{fill:'var(--sci)',fo:.2,c:'var(--ink)',w:2}).dot(1,1,{l:'A'}).dot(7,3,{l:'B'}).dot(5,9,{l:'C'}); return P.svg(); })(),
   parts:[
    {q:'a) Combien vaut AB² ?',lab:'AB² =',ans:40,hint:'AB² = (xB − xA)² + (yB − yA)².',why:'(7 − 1)² + (3 − 1)² = 36 + 4 = 40.'},
    {q:'b) Combien vaut AC² ?',lab:'AC² =',ans:80,hint:'Même méthode avec A et C.',why:'(5 − 1)² + (9 − 1)² = 16 + 64 = 80.'},
    {q:'c) Sachant que BC² = 40, que conclut-on ?',opts:['Le triangle est rectangle en A','Le triangle est rectangle en B','Le triangle n’est pas rectangle','Le triangle est équilatéral'],ans:1,hint:'L’angle droit est en face du plus grand côté.',why:'AB² + BC² = 40 + 40 = 80 = AC². Par la réciproque de Pythagore, l’angle droit est en B, face à [AC].'},
    {q:'d) Quelle est l’aire du triangle ?',unit:'m²',ans:20,hint:'Dans un triangle rectangle, les deux côtés de l’angle droit sont base et hauteur.',why:'AB = BC = √40, donc aire = √40 · √40 ÷ 2 = 40 ÷ 2 = 20 m².'},
   ],
   sol:'AB² = 6² + 2² = 40, BC² = 2² + 6² = 40, AC² = 4² + 8² = 80.<br>Comme AB² + BC² = AC², la réciproque de Pythagore dit que le triangle est rectangle en B.<br>Il est aussi isocèle (AB = BC).<br>Aire = AB · BC ÷ 2 = 40 ÷ 2 = 20 m². On n’a même pas besoin de calculer √40.'},
 ]},

{id:'aires',br:'geo',lv:'ecole',h:'Aires et périmètres',p:'Du rectangle au disque, découper et recoller.',
 lessons:['Le parallélogramme','Triangles et trapèzes','Le disque et π','Volumes de solides'],
 steps:[
  {h:'Pencher sans changer l’aire',p:'Coupe le triangle de gauche d’un parallélogramme, recolle-le à droite : tu obtiens un rectangle. Son aire vaut toujours <b>base × hauteur</b>.',
   params:[{id:'s',l:'Inclinaison',min:-3,max:3,step:.5,v:1.5}],
   draw:v=>{ const P=plane({x:[-3.5,8.5],y:[-1,4],grid:false,axes:false});
     P.poly([[0,0],[5,0],[5+v.s,3],[v.s,3]],{fill:'var(--math)',fo:.3,c:'var(--ink)',w:2}).rect(0,0,5,3,{c:'var(--muted)',w:1.5,dash:true});
     P.seg(v.s,3,v.s,0,{c:'var(--spark)',w:2,dash:true}).text(2.5,0,'base 5',{a:'middle',dy:18}).text(v.s,1.5,'h = 3',{dx:6}); return P.svg(); },
   info:()=>'Aire = 5 × 3 = 15, quelle que soit l’inclinaison.'},
  {h:'Le triangle',p:'Un triangle a une base de 10 cm et une hauteur de 6 cm. Quelle est son aire&nbsp;?',unit:'cm²',ans:30,why:'Un triangle est la moitié d’un parallélogramme : 10 × 6 ÷ 2 = 30 cm².'},
  {h:'Le disque',p:'Aire d’un disque de rayon 3 cm, arrondie au centième&nbsp;?',unit:'cm²',ans:28.27,tol:.011,why:'A = π·r² = π × 9 ≈ 28,27 cm².'},
  {kind:'Défi',h:'Changer d’échelle',p:'Si on double le côté d’un carré, son aire est…',opts:['doublée','multipliée par 4','multipliée par 8','inchangée'],ans:1,why:'(2c)² = 4c². L’aire grandit comme le carré des longueurs.'},
  {kind:'Problème',h:'Repeindre le mur',
   p:'Tu repeins un mur de 4,5 m de large et 2,5 m de haut. Il contient une porte de 0,9 m sur 2 m et une fenêtre ronde de rayon 0,4 m, qu’on ne peint pas. Il faut deux couches, et un pot couvre 5 m².',
   parts:[
    {q:'a) Quelle est l’aire du mur entier ?',unit:'m²',ans:11.25,tol:.001,hint:'C’est un rectangle.',why:'4,5 × 2,5 = 11,25 m².'},
    {q:'b) Quelle aire faut-il peindre (une couche, au centième) ?',unit:'m²',ans:8.95,tol:.011,hint:'Retire la porte et le disque π·r².',why:'11,25 − 1,8 − π·0,4² ≈ 11,25 − 1,8 − 0,50 ≈ 8,95 m².'},
    {q:'c) Combien de pots faut-il acheter ?',unit:'pots',ans:4,hint:'Deux couches, et on n’achète pas de demi-pot.',why:'2 × 8,95 ≈ 17,9 m², et 17,9 ÷ 5 ≈ 3,58. Il faut 4 pots.'},
   ],
   sol:'Mur : 4,5 × 2,5 = 11,25 m². Porte : 0,9 × 2 = 1,8 m². Fenêtre : π × 0,4² ≈ 0,50 m².<br>À peindre : 11,25 − 1,8 − 0,50 ≈ 8,95 m² par couche.<br>Deux couches : ≈ 17,89 m², soit 17,89 ÷ 5 ≈ 3,58 pots.<br>On arrondit vers le haut : 4 pots.'},
  {kind:'Problème',h:'La piste d’athlétisme',
   p:'Une piste simplifiée est formée de deux lignes droites de 100 m et de deux virages en demi-cercle de 60 m de diamètre. On mesure au bord intérieur. On veut son périmètre, l’aire qu’elle entoure, puis comprendre pourquoi les coureurs extérieurs partent plus loin.',
   fig:(()=>{ const P=plane({x:[-45,145],y:[-40,40],w:320,grid:false,axes:false}); P.curve(t=>t<1?100*t:t<2?100+30*Math.sin(Math.PI*(t-1)):t<3?100-100*(t-2):-30*Math.sin(Math.PI*(t-3)),t=>t<1?-30:t<2?-30*Math.cos(Math.PI*(t-1)):t<3?30:30*Math.cos(Math.PI*(t-3)),0,4,{n:400,c:'var(--ink)',w:2.5}); P.text(50,-30,'100 m',{a:'middle',dy:-8}).seg(100,-30,100,30,{c:'var(--muted)',w:1.5,dash:true}).text(100,0,'60 m',{dx:6}); return P.svg(); })(),
   parts:[
    {q:'a) Quel est le périmètre intérieur de la piste ? (au centième)',unit:'m',ans:388.5,tol:.011,hint:'Les deux demi-cercles forment un cercle entier de diamètre 60 m.',why:'2 × 100 + π × 60 ≈ 200 + 188,50 = 388,50 m.'},
    {q:'b) Quelle aire la piste entoure-t-elle ? (au m² près)',unit:'m²',ans:8827,tol:1,hint:'Un rectangle 100 × 60 et un disque de rayon 30.',why:'100 × 60 + π × 30² ≈ 6000 + 2827 = 8827 m².'},
    {q:'c) Quelle longueur faudrait-il donner aux lignes droites pour que le tour fasse 400 m ? (au centième)',unit:'m',ans:105.75,tol:.011,hint:'Résous 2L + 60π = 400.',why:'L = (400 − 60π) ÷ 2 ≈ 105,75 m.'},
    {q:'d) Un coureur tourne à 1,22 m à l’extérieur du bord intérieur. Combien de mètres de plus parcourt-il par tour ? (au centième)',unit:'m',ans:7.67,tol:.011,hint:'Les lignes droites ne changent pas. Seul le diamètre des virages augmente, de 2 × 1,22 m.',why:'π × (60 + 2,44) − π × 60 = π × 2,44 ≈ 7,67 m, quelle que soit la longueur des lignes droites.'},
   ],
   sol:'Périmètre : 2 × 100 + π × 60 ≈ 388,50 m. Aire : 6000 + π × 900 ≈ 8827 m².<br>Pour un tour de 400 m : 2L = 400 − 60π, donc L ≈ 105,75 m.<br>Couloir extérieur : le diamètre des virages passe à 62,44 m. Le tour s’allonge de π × 2,44 ≈ 7,67 m.<br>Ce supplément ne dépend que de l’écart entre les couloirs : c’est pourquoi les départs sont décalés.'},
 ]},

{id:'thales',br:'geo',lv:'ecole',h:'Thalès et agrandissements',p:'Mesurer un arbre avec son ombre, lire une carte.',
 lessons:['Agrandir et réduire','Le théorème de Thalès','Mesurer l’inaccessible','Échelles des cartes'],
 steps:[
  {h:'Agrandir d’un facteur k',p:'Quand on agrandit une figure d’un facteur <i>k</i>, toutes les longueurs sont multipliées par <i>k</i>. Les angles ne changent pas.',
   params:[{id:'k',l:'Facteur k',min:.5,max:3,step:.25,v:2}],
   draw:v=>{ const P=plane({x:[-0.5,9],y:[-0.5,6],grid:false,axes:false}); const t=[[0,0],[2,0],[0.6,1.6]];
     P.poly(t.map(p=>[p[0]*v.k,p[1]*v.k]),{fill:'var(--math)',fo:.25,c:'var(--math)',w:2.5}).poly(t,{fill:'var(--spark)',fo:.6,c:'var(--ink)',w:1.5});
     return P.svg(); },
   info:v=>`Périmètre × ${fmt(v.k)} · Aire × ${fmt(v.k*v.k,4)}`},
  {h:'L’arbre et son ombre',p:'Un bâton de 1 m fait une ombre de 1,5 m. Au même moment, un arbre fait une ombre de 12 m. Quelle est la hauteur de l’arbre&nbsp;?',
   fig:(()=>{ const P=plane({x:[-0.5,13],y:[-1,9],grid:false,axes:false,w:300}); P.seg(-0.3,0,12.8,0,{c:'var(--muted)',w:2}).seg(0,0,0,8,{c:'var(--sci)',w:6}).seg(0,8,12,0,{c:'var(--spark)',w:2,dash:true})
     .seg(4,0,4,1,{c:'var(--ink)',w:4}).seg(4,1,5.5,0,{c:'var(--spark)',w:2,dash:true}).text(6,0,'12 m',{a:'middle',dy:18}).text(0,4,'?',{dx:10,s:16}); return P.svg(); })(),
   unit:'m',ans:8,why:'Les rayons du soleil sont parallèles : les triangles sont semblables. 12 ÷ 1,5 = 8, donc l’arbre mesure 8 × 1 m = 8 m.'},
  {h:'Lire une carte',p:'Sur une carte nationale au 1:25 000, 4 cm représentent…',opts:['250 m','1 km','4 km','10 km'],ans:1,why:'4 × 25 000 = 100 000 cm = 1 000 m = 1 km.'},
  {kind:'Défi',h:'Et l’aire&nbsp;?',p:'On agrandit une photo d’un facteur 3. Par combien son aire est-elle multipliée&nbsp;?',lab:'×',ans:9,why:'Les longueurs sont × 3, donc l’aire est × 3² = 9.'},
  {kind:'Problème',h:'Le plan au 1:50',
   p:'Sur un plan à l’échelle 1:50, ta chambre est un rectangle de 8 cm sur 7 cm. Tu veux connaître ses vraies dimensions, puis dessiner ton lit, qui mesure 2 m sur 0,9 m.',
   parts:[
    {q:'a) Quelle est la vraie longueur de la chambre ?',unit:'m',ans:4,tol:.001,hint:'1 cm sur le plan vaut 50 cm en vrai.',why:'8 × 50 = 400 cm = 4 m.'},
    {q:'b) Quelle est la vraie aire de la chambre ?',unit:'m²',ans:14,tol:.001,hint:'Calcule d’abord la vraie largeur.',why:'Largeur : 7 × 50 = 350 cm = 3,5 m. Aire : 4 × 3,5 = 14 m².'},
    {q:'c) Par combien faut-il multiplier l’aire du plan (en cm²) pour obtenir l’aire réelle (en cm²) ?',lab:'×',ans:2500,hint:'Les longueurs sont multipliées par 50.',why:'Les aires sont multipliées par 50² = 2500 : 56 cm² × 2500 = 140 000 cm² = 14 m².'},
    {q:'d) Quelle aire occupe le lit sur le plan ?',unit:'cm²',ans:7.2,tol:.001,hint:'Divise chaque dimension réelle par 50.',why:'200 ÷ 50 = 4 cm et 90 ÷ 50 = 1,8 cm, donc 4 × 1,8 = 7,2 cm².'},
   ],
   sol:'Dimensions réelles : 8 × 50 = 400 cm et 7 × 50 = 350 cm, soit 4 m sur 3,5 m, donc 14 m².<br>Sur le plan, l’aire est 8 × 7 = 56 cm². Le rapport des aires vaut 50² = 2500.<br>Le lit se dessine en 4 cm sur 1,8 cm, soit 7,2 cm².<br>Contrôle : 7,2 × 2500 = 18 000 cm² = 1,8 m² = 2 × 0,9.'},
  {kind:'Problème',h:'La largeur de la rivière',
   p:'Zoé veut mesurer une rivière sans la traverser. Elle se place en A, face à un arbre T sur l’autre rive. Elle longe la berge sur 30 m jusqu’au piquet B, puis encore 10 m jusqu’en C. Là, elle s’éloigne de la rivière à angle droit jusqu’au point D, où elle voit B et l’arbre alignés : CD = 6 m.',
   fig:(()=>{ const P=plane({x:[-4,44],y:[-9,22],w:320,grid:false,axes:false}); P.rect(-4,0,48,18,{fill:'var(--sci)',fo:.15,c:null}).seg(-4,0,44,0,{c:'var(--muted)',w:1.5}).seg(-4,18,44,18,{c:'var(--muted)',w:1.5});
     P.seg(0,0,0,18,{c:'var(--ink)',w:2,dash:true}).seg(0,18,40,-6,{c:'var(--spark)',w:2}).seg(0,0,40,0,{c:'var(--ink)',w:2}).seg(40,0,40,-6,{c:'var(--ink)',w:2});
     P.dot(0,0,{l:'A',dx:-16,dy:14}).dot(0,18,{l:'T'}).dot(30,0,{l:'B',dx:-4,dy:16}).dot(40,0,{l:'C'}).dot(40,-6,{l:'D'}).text(15,0,'30 m',{a:'middle',dy:14,s:11}).text(35,0,'10',{a:'middle',dy:-6,s:11}).text(40,-3,'6 m',{dx:8,s:11}); return P.svg(); })(),
   parts:[
    {q:'a) Pourquoi les triangles TAB et DCB sont-ils semblables ?',opts:['Parce que AB = 3 · BC','Ils ont deux angles égaux : un angle droit et les angles opposés en B','Parce que la rivière est droite','Parce que CD = 6 m'],ans:1,hint:'Regarde les angles en A, en C et en B.',why:'Les angles en A et en C sont droits, et les angles en B sont opposés par le sommet. Deux angles égaux suffisent.'},
    {q:'b) Quelle est la largeur AT de la rivière ?',unit:'m',ans:18,hint:'AT ÷ CD = AB ÷ BC.',why:'AT = CD × AB ÷ BC = 6 × 30 ÷ 10 = 18 m.'},
    {q:'c) Un autre jour, Zoé prend AB = 24 m et BC = 8 m. À quelle distance CD verra-t-elle l’alignement ?',unit:'m',ans:6,hint:'La largeur de la rivière n’a pas changé.',why:'CD = AT × BC ÷ AB = 18 × 8 ÷ 24 = 6 m.'},
    {q:'d) Avec les mesures de départ, Zoé s’est trompée : en vrai CD = 6,5 m. De combien de mètres sa largeur était-elle fausse ?',unit:'m',ans:1.5,tol:.001,hint:'Recalcule AT avec 6,5 m.',why:'6,5 × 3 = 19,5 m au lieu de 18 m : une erreur de 1,5 m. L’erreur sur CD est multipliée par AB ÷ BC = 3.'},
   ],
   sol:'Les triangles TAB et DCB ont un angle droit (en A et en C) et des angles opposés par le sommet en B : ils sont semblables.<br>Donc AT ÷ CD = AB ÷ BC = 30 ÷ 10 = 3, et AT = 3 × 6 = 18 m.<br>Avec AB = 24 et BC = 8, le rapport reste 3 : CD = 18 ÷ 3 = 6 m.<br>Une erreur de 0,5 m sur CD devient 3 × 0,5 = 1,5 m sur la largeur. Pour être précis, il vaut mieux un rapport AB ÷ BC petit.'},
 ]},

/* ================= GYMNASE ================= */
{id:'second',br:'alg',lv:'gym',h:'Équations du 2e degré',p:'Paraboles, racines et discriminant.',
 lessons:['Paraboles et racines','Le discriminant','Forme canonique','Somme et produit des racines'],
 steps:[
  {h:'Où la parabole coupe-t-elle l’axe&nbsp;?',p:'Résoudre <i>x² + bx + c = 0</i>, c’est chercher où la parabole <i>y = x² + bx + c</i> touche l’axe horizontal. Il peut y avoir 2, 1 ou 0 solutions.',
   params:[{id:'b',l:'b',min:-6,max:6,v:-2},{id:'c',l:'c',min:-6,max:6,v:-3}],
   draw:v=>{ const P=plane({x:[-6,6],y:[-6,6],lab:2}); P.fn(x=>x*x+v.b*x+v.c); const D=v.b*v.b-4*v.c;
     if(D>=0){ [(-v.b-Math.sqrt(D))/2,(-v.b+Math.sqrt(D))/2].forEach(r=>P.dot(r,0)); } return P.svg(); },
   info:v=>{ const D=v.b*v.b-4*v.c; return `Δ = b² − 4c = ${fmt(D)} → ${D>0?'2 solutions':D===0?'1 solution (double)':'aucune solution réelle'}`; }},
  {h:'Factoriser pour résoudre',p:'Résous <i>x² − 5x + 6 = 0</i>.',opts:['x = 2 ou x = 3','x = −2 ou x = −3','x = 1 ou x = 6','Pas de solution'],ans:0,
   why:'x² − 5x + 6 = (x − 2)(x − 3). Un produit est nul si l’un des facteurs l’est.'},
  {h:'Une seule racine',p:'Règle <i>c</i> pour que <i>y = x² − 4x + c</i> touche l’axe en un seul point.',
   params:[{id:'c',l:'c',min:-4,max:8,v:0}],
   draw:v=>{ const P=plane({x:[-3,7],y:[-5,5],lab:2}); P.fn(x=>x*x-4*x+v.c); return P.svg(); },
   ok:v=>v.c===4,why:'Une seule racine quand Δ = 0 : 16 − 4c = 0, donc c = 4. On obtient (x − 2)².'},
  {kind:'Défi',h:'Le discriminant',p:'Calcule le discriminant de <i>2x² + 3x − 2</i>.',lab:'Δ =',ans:25,why:'Δ = b² − 4ac = 9 − 4·2·(−2) = 9 + 16 = 25. Les racines sont ½ et −2.'},
  {kind:'Problème',h:'Le lancer de ballon',
   p:'Un ballon est lancé vers le haut depuis une hauteur de 1,8 m. Sa hauteur (en m) après <i>t</i> secondes vaut <i>h(t) = −5t² + 20t + 1,8</i>. On cherche le sommet de la trajectoire et l’instant où le ballon touche le sol.',
   fig:(()=>{ const P=plane({x:[-0.5,5],y:[-2,24],w:300,h:220,grid:false,lx:1,ly:5}); P.fn(t=>-5*t*t+20*t+1.8,{from:0,to:4.09}).dot(2,21.8,{l:'sommet'}); return P.svg(); })(),
   parts:[
    {q:'a) À quel instant le ballon est-il au plus haut ?',lab:'t =',unit:'s',ans:2,tol:.001,hint:'Le sommet d’une parabole ax² + bx + c est en −b/(2a).',why:'t = −20 ÷ (2 · (−5)) = 2 s.'},
    {q:'b) Quelle hauteur maximale atteint-il ?',unit:'m',ans:21.8,tol:.001,hint:'Calcule h(2).',why:'h(2) = −20 + 40 + 1,8 = 21,8 m.'},
    {q:'c) Quand touche-t-il le sol ? (au centième)',lab:'t =',unit:'s',ans:4.09,tol:.011,hint:'Résous −5t² + 20t + 1,8 = 0 avec le discriminant.',why:'Δ = 400 + 36 = 436. t = (−20 − √436) ÷ (−10) ≈ 4,09 s.'},
    {q:'d) L’autre racine vaut environ −0,09. Que faire de cette solution ?',opts:['C’est l’instant où le ballon retombe','On l’écarte : le lancer commence à t = 0','Elle prouve qu’il y a une erreur dans le modèle','On la garde : le temps peut être négatif'],ans:1,hint:'Sur quel intervalle de temps le modèle décrit-il le vol ?',why:'Le modèle ne vaut que pour t ≥ 0. La racine négative correspond à une parabole prolongée avant le lancer.'},
   ],
   sol:'Sommet : t = −b/(2a) = 2 s et h(2) = 21,8 m.<br>Sol : −5t² + 20t + 1,8 = 0, Δ = 20² − 4 · (−5) · 1,8 = 436.<br>t = (20 ± √436) ÷ 10, soit t ≈ 4,09 s ou t ≈ −0,09 s.<br>Seule la racine positive a un sens : le ballon touche le sol après environ 4,09 s.'},
  {kind:'Problème',h:'L’enclos contre le mur',
   p:'Avec 40 m de grillage, on fabrique un enclos rectangulaire adossé à un long mur : le grillage ne couvre que trois côtés. On note <i>x</i> la largeur perpendiculaire au mur. L’aire vaut alors <i>A(x) = x(40 − 2x)</i>. Quelles aires sont possibles&nbsp;?',
   parts:[
    {q:'a) Quelle est l’aire pour x = 5 m ?',unit:'m²',ans:150,hint:'Le côté parallèle au mur mesure 40 − 2x.',why:'5 × 30 = 150 m².'},
    {q:'b) Une autre largeur donne aussi 150 m². Sans résoudre, combien vaut la somme des deux largeurs possibles ?',unit:'m',ans:20,hint:'Écris x(40 − 2x) = 150 sous la forme x² + px + q = 0. La somme des racines vaut −p.',why:'2x² − 40x + 150 = 0, soit x² − 20x + 75 = 0. La somme des racines vaut 20.'},
    {q:'c) Quelle est l’autre largeur ?',lab:'x =',unit:'m',ans:15,hint:'Utilise la somme trouvée en b).',why:'20 − 5 = 15 m. Contrôle : 15 × 10 = 150 m², et le produit des racines vaut bien 5 × 15 = 75.'},
    {q:'d) Quelle est la plus grande aire A pour laquelle l’équation x(40 − 2x) = A a une solution ?',unit:'m²',ans:200,hint:'x² − 20x + A/2 = 0 a une solution si Δ ≥ 0.',why:'Δ = 400 − 2A ≥ 0 donne A ≤ 200. Le maximum 200 m² est atteint pour la racine double x = 10.'},
   ],
   sol:'A(x) = x(40 − 2x). A(5) = 150 m².<br>A(x) = 150 donne x² − 20x + 75 = 0 : somme des racines 20, produit 75, donc x = 5 ou x = 15.<br>En général, x² − 20x + A/2 = 0 a une solution si Δ = 400 − 2A ≥ 0, donc A ≤ 200.<br>Pour A = 200, la racine est double : x = 10 m. L’enclos optimal mesure 10 m sur 20 m.'},
 ]},

{id:'systemes',br:'alg',lv:'gym',h:'Systèmes d’équations',p:'Deux inconnues, deux droites, un point de rencontre.',
 lessons:['Deux droites qui se croisent','Substitution','Combinaison linéaire','Systèmes 3 × 3'],
 steps:[
  {h:'Résoudre = trouver l’intersection',p:'Chaque équation à deux inconnues est une droite. La solution du système est le point commun aux deux droites. La bleue est <i>x + y = 5</i>.',
   params:[{id:'a',l:'Pente de la rouge',min:-3,max:3,step:.5,v:1},{id:'b',l:'Ordonnée de la rouge',min:-4,max:4,v:-1}],
   draw:v=>{ const P=plane({x:[-6,6],y:[-6,6],lab:2}); P.fn(x=>5-x,{c:'var(--math)'}).fn(x=>v.a*x+v.b,{c:'var(--bad)'});
     if(v.a!==-1){ const x=(5-v.b)/(v.a+1); P.dot(x,5-x); } return P.svg(); },
   info:v=>{ if(v.a===-1) return v.b===5?'Droites confondues : une infinité de solutions':'Droites parallèles : aucune solution'; const x=(5-v.b)/(v.a+1); return `Solution : x = ${fmt(x)}, y = ${fmt(5-x)}`; }},
  {h:'À toi',p:'Résous : <i>x + y = 10</i> et <i>x − y = 2</i>.',opts:['(6 ; 4)','(4 ; 6)','(5 ; 5)','(8 ; 2)'],ans:0,why:'En additionnant les deux équations : 2x = 12, donc x = 6 et y = 4.'},
  {h:'Aucune solution',p:'La droite bleue est <i>y = 2x + 1</i>. Règle la rouge pour que le système n’ait <b>aucune</b> solution.',
   params:[{id:'a',l:'Pente',min:-3,max:3,step:.5,v:0},{id:'b',l:'Ordonnée',min:-4,max:4,v:1}],
   draw:v=>{ const P=plane({x:[-5,5],y:[-5,5],lab:2}); P.fn(x=>2*x+1,{c:'var(--math)'}).fn(x=>v.a*x+v.b,{c:'var(--bad)'}); return P.svg(); },
   ok:v=>v.a===2&&v.b!==1,why:'Pas de solution quand les droites sont parallèles et distinctes : même pente (2), ordonnée différente.'},
  {kind:'Défi',h:'Au cinéma',p:'3 adultes et 2 enfants paient 61 CHF. 1 adulte et 2 enfants paient 31 CHF. Combien coûte un billet adulte&nbsp;?',unit:'CHF',ans:15,
   why:'3A + 2E = 61 et A + 2E = 31. On soustrait : 2A = 30, donc A = 15 CHF (et E = 8 CHF).'},
  {kind:'Problème',h:'Le stand de crêpes',
   p:'Lors d’une fête, un stand vend des crêpes à 4 CHF et des gaufres à 5 CHF. En une soirée, il vend 120 pièces et encaisse 530 CHF. On note <i>c</i> le nombre de crêpes et <i>g</i> le nombre de gaufres.',
   parts:[
    {q:'a) Quel système traduit la situation ?',opts:['c + g = 530 et 4c + 5g = 120','c + g = 120 et 5c + 4g = 530','c + g = 120 et 4c + 5g = 530','4c = 5g et c + g = 120'],ans:2,hint:'Une équation compte les pièces, l’autre l’argent.',why:'Pièces : c + g = 120. Argent : 4c + 5g = 530.'},
    {q:'b) Combien de gaufres ont été vendues ?',lab:'g =',ans:50,hint:'Multiplie la 1re équation par 4 et soustrais.',why:'4c + 5g − (4c + 4g) = 530 − 480, donc g = 50.'},
    {q:'c) Combien de crêpes ?',lab:'c =',ans:70,hint:'Utilise c + g = 120.',why:'c = 120 − 50 = 70.'},
    {q:'d) Le bénéfice est de 1,50 CHF par crêpe et 2 CHF par gaufre. Quel est le bénéfice de la soirée ?',unit:'CHF',ans:205,tol:.001,hint:'Utilise les valeurs de c et g.',why:'70 × 1,5 + 50 × 2 = 105 + 100 = 205 CHF.'},
   ],
   sol:'Système : c + g = 120 et 4c + 5g = 530.<br>On multiplie la première par 4 : 4c + 4g = 480. On soustrait : g = 50, puis c = 70.<br>Contrôle : 4 × 70 + 5 × 50 = 280 + 250 = 530 CHF.<br>Bénéfice : 70 × 1,50 + 50 × 2 = 205 CHF.'},
  {kind:'Problème',h:'La parabole par trois points',
   p:'On cherche la parabole <i>y = ax² + bx + c</i> qui passe par les points (1 ; 2), (2 ; 3) et (−1 ; 6). Chaque point donne une équation linéaire en <i>a</i>, <i>b</i>, <i>c</i> : on obtient un système 3 × 3.',
   parts:[
    {q:'a) Le point (1 ; 2) donne a + b + c = 2 et le point (−1 ; 6) donne a − b + c = 6. En les combinant, que vaut b ?',lab:'b =',ans:-2,hint:'Soustrais les deux équations : a et c disparaissent.',why:'(a + b + c) − (a − b + c) = 2b = 2 − 6 = −4, donc b = −2.'},
    {q:'b) Le point (2 ; 3) donne 4a + 2b + c = 3. Combien vaut a ?',lab:'a =',ans:1,hint:'Soustrais a + b + c = 2 de cette équation, puis remplace b.',why:'3a + b = 1, donc 3a = 3 et a = 1.'},
    {q:'c) Combien vaut c ?',lab:'c =',ans:3,hint:'a + b + c = 2.',why:'c = 2 − 1 + 2 = 3. La parabole est y = x² − 2x + 3.'},
    {q:'d) Quelle est l’ordonnée du sommet de cette parabole ?',lab:'y =',ans:2,hint:'Le sommet est en x = −b/(2a).',why:'x = 1, y = 1 − 2 + 3 = 2. Le point (1 ; 2) est donc le sommet.'},
   ],
   sol:'Les trois points donnent : a + b + c = 2, 4a + 2b + c = 3, a − b + c = 6.<br>(1) − (3) : 2b = −4, donc b = −2. (2) − (1) : 3a + b = 1, donc a = 1. Puis c = 3.<br>La parabole est y = x² − 2x + 3 = (x − 1)² + 2.<br>Contrôle : en x = 2, 4 − 4 + 3 = 3 ; en x = −1, 1 + 2 + 3 = 6. Son sommet est (1 ; 2).'},
 ]},

{id:'explog',br:'alg',lv:'gym',h:'Exponentielles et logarithmes',p:'Doublements, intérêts composés et échelles log.',
 lessons:['Croissance exponentielle','Le logarithme','Lois des logarithmes','Équations exponentielles'],
 steps:[
  {h:'Multiplier à chaque pas',p:'Une fonction exponentielle <i>y = a·bˣ</i> est multipliée par <i>b</i> chaque fois que <i>x</i> augmente de 1.',
   params:[{id:'a',l:'a (valeur en 0)',min:.5,max:3,step:.5,v:1},{id:'b',l:'b (facteur)',min:.25,max:3,step:.25,v:2}],
   draw:v=>{ const P=plane({x:[-4,4],y:[-1,7]}); P.fn(x=>v.a*Math.pow(v.b,x)).dot(0,v.a,{l:`(0 ; ${fmt(v.a)})`}); return P.svg(); },
   info:v=>v.b>1?'b > 1 : croissance, de plus en plus rapide':v.b<1?'b < 1 : décroissance vers 0':'b = 1 : constante'},
  {h:'Les bactéries',p:'Une colonie de 100 bactéries double chaque heure. Combien y en a-t-il après 5 heures&nbsp;?',opts:['500','1 000','3 200','10 000'],ans:2,why:'100 × 2⁵ = 100 × 32 = 3 200.'},
  {h:'Le logarithme',p:'Le logarithme répond à la question « à quelle puissance&nbsp;? ». Combien vaut <i>log₂(64)</i>&nbsp;?',ans:6,why:'2⁶ = 64, donc log₂(64) = 6.'},
  {kind:'Défi',h:'Intérêts composés',p:'Tu places 1 000 CHF à 5 % par an, intérêts composés. Combien as-tu après 2 ans&nbsp;?',unit:'CHF',ans:1102.5,tol:.001,why:'1 000 × 1,05 × 1,05 = 1 102,50 CHF. Les intérêts de la 2e année portent aussi sur ceux de la 1re.'},
  {kind:'Problème',h:'Une ville qui grandit',
   p:'Une ville compte 20 000 habitants. Sa population augmente de 3 % par an. On note <i>P(n) = 20 000 · 1,03ⁿ</i> la population après <i>n</i> années. On veut prévoir quand elle atteindra certains seuils.',
   parts:[
    {q:'a) Combien d’habitants après 10 ans ? (à l’unité près)',ans:26878,tol:1,hint:'Calcule 20 000 · 1,03¹⁰.',why:'20 000 · 1,03¹⁰ ≈ 26 878 habitants.'},
    {q:'b) Après combien d’années entières la ville dépasse-t-elle 30 000 habitants ?',unit:'ans',ans:14,hint:'Résous 1,03ⁿ ≥ 1,5 avec le logarithme.',why:'n ≥ ln 1,5 ÷ ln 1,03 ≈ 13,7. Il faut 14 ans.'},
    {q:'c) Quel est le temps de doublement ? (au dixième)',unit:'ans',ans:23.4,tol:.051,hint:'Résous 1,03ⁿ = 2.',why:'n = ln 2 ÷ ln 1,03 ≈ 23,4 ans, quelle que soit la population de départ.'},
   ],
   sol:'P(10) = 20 000 · 1,03¹⁰ ≈ 26 878.<br>P(n) ≥ 30 000 ⟺ 1,03ⁿ ≥ 1,5 ⟺ n · ln 1,03 ≥ ln 1,5 ⟺ n ≥ 13,72. Il faut 14 ans.<br>Doublement : 1,03ⁿ = 2 donne n = ln 2 ÷ ln 1,03 ≈ 23,4 ans.<br>Le temps de doublement ne dépend pas de la population initiale : c’est la marque d’une croissance exponentielle.'},
  {kind:'Problème',h:'Le médicament dans le sang',
   p:'On injecte 400 mg d’un médicament. Chaque heure, le corps en élimine 20 %. La quantité restante après <i>t</i> heures est <i>Q(t) = 400 · 0,8ᵗ</i>. Le médicament agit tant qu’il en reste au moins 50 mg.',
   parts:[
    {q:'a) Quelle quantité reste-t-il après 3 heures ?',unit:'mg',ans:204.8,tol:.001,hint:'0,8³ = 0,512.',why:'400 × 0,512 = 204,8 mg.'},
    {q:'b) Quelle est la demi-vie du médicament ? (au centième)',unit:'h',ans:3.11,tol:.011,hint:'Résous 0,8ᵗ = 0,5.',why:'t = ln 0,5 ÷ ln 0,8 ≈ 3,11 h.'},
    {q:'c) On résout 0,8ᵗ ≥ 0,125 en prenant le logarithme : t · ln 0,8 ≥ ln 0,125. Pourquoi obtient-on t ≤ … et non t ≥ … ?',opts:['Parce que ln 0,125 est négatif','Parce que ln 0,8 est négatif et qu’on divise par lui','Parce que la fonction ln est décroissante','Parce que 0,125 < 0,8'],ans:1,hint:'Que se passe-t-il quand on divise une inégalité par un nombre négatif ?',why:'ln 0,8 < 0. Diviser par un négatif renverse l’inégalité. Le ln, lui, est croissant.'},
    {q:'d) Pendant combien d’heures le médicament agit-il ? (au centième)',unit:'h',ans:9.32,tol:.011,hint:'400 · 0,8ᵗ ≥ 50 ⟺ 0,8ᵗ ≥ 0,125.',why:'t ≤ ln 0,125 ÷ ln 0,8 ≈ 9,32 h. C’est exactement 3 demi-vies : 400 → 200 → 100 → 50.'},
   ],
   sol:'Q(3) = 400 · 0,8³ = 204,8 mg.<br>Demi-vie : 0,8ᵗ = 0,5 donne t = ln 0,5 ÷ ln 0,8 ≈ 3,11 h.<br>Action : 0,8ᵗ ≥ 0,125 ⟺ t · ln 0,8 ≥ ln 0,125 ⟺ t ≤ ln 0,125 ÷ ln 0,8 (on divise par ln 0,8 < 0).<br>Donc t ≤ 9,32 h. Comme 0,125 = 0,5³, c’est trois demi-vies : 3 × 3,11 ≈ 9,32 h.'},
 ]},

{id:'graphes',br:'ana',lv:'gym',h:'Fonctions et graphes',p:'Décaler, étirer et retourner des courbes.',
 lessons:['Transformer un graphe','Fonctions paires et impaires','Composition','Fonction réciproque'],
 steps:[
  {h:'y = a·(x − h)² + k',p:'À partir de <i>y = x²</i> (pointillé), <i>h</i> décale à droite, <i>k</i> décale vers le haut, <i>a</i> étire ou retourne.',
   params:[{id:'a',l:'a',min:-2,max:2,step:.5,v:1},{id:'h',l:'h',min:-3,max:3,v:0},{id:'k',l:'k',min:-3,max:3,v:0}],
   draw:v=>{ const P=plane({x:[-5,5],y:[-5,5],lab:2}); P.fn(x=>x*x,{c:'var(--muted)',dash:true,w:2}).fn(x=>v.a*(x-v.h)**2+v.k).dot(v.h,v.k,{l:'sommet'}); return P.svg(); },
   info:v=>`Sommet en (${fmt(v.h)} ; ${fmt(v.k)})`},
  {h:'Superpose les paraboles',p:'Règle les curseurs pour que ta parabole recouvre la parabole jaune pointillée.',
   params:[{id:'a',l:'a',min:-2,max:2,step:.5,v:-1},{id:'h',l:'h',min:-3,max:3,v:0},{id:'k',l:'k',min:-3,max:3,v:1}],
   draw:v=>{ const P=plane({x:[-5,5],y:[-5,5],lab:2}); P.fn(x=>(x-2)**2-1,{c:'var(--spark)',dash:true,w:5}).fn(x=>v.a*(x-v.h)**2+v.k); return P.svg(); },
   ok:v=>v.a===1&&v.h===2&&v.k===-1,why:'Le sommet jaune est en (2 ; −1) et la courbe a la largeur de x² : y = (x − 2)² − 1.'},
  {h:'Dans quel sens&nbsp;?',p:'Par rapport à <i>y = x²</i>, le graphe de <i>y = (x + 3)²</i> est…',opts:['décalé de 3 vers la droite','décalé de 3 vers la gauche','décalé de 3 vers le haut','étiré verticalement'],ans:1,
   why:'Il faut x = −3 pour retrouver 0². Tout arrive 3 unités plus tôt, donc à gauche.'},
  {kind:'Défi',h:'Fonction paire',p:'Quelle fonction a un graphe symétrique par rapport à l’axe vertical&nbsp;?',opts:['x³','x² + 1','x + 1','√x'],ans:1,why:'f(−x) = (−x)² + 1 = x² + 1 = f(x). C’est la définition d’une fonction paire.'},
  {kind:'Problème',h:'Trois transformations à la suite',
   p:'On part du graphe de <i>f(x) = x²</i>. On le décale d’abord de 3 vers la droite, puis on l’étire verticalement d’un facteur 2, enfin on le décale de 5 vers le bas. On note <i>g</i> la fonction obtenue.',
   fig:(()=>{ const P=plane({x:[-2,8],y:[-6,6],lab:2}); P.fn(x=>x*x,{c:'var(--muted)',dash:true,w:2}).fn(x=>2*(x-3)**2-5).dot(3,-5,{l:'sommet'}); return P.svg(); })(),
   parts:[
    {q:'a) Quelle est l’expression de g ?',opts:['2(x + 3)² − 5','2(x − 3)² − 10','2(x − 3)² − 5','(2x − 3)² − 5'],ans:2,hint:'Applique les transformations dans l’ordre. L’étirement agit avant le décalage vers le bas.',why:'(x − 3)², puis 2(x − 3)², puis 2(x − 3)² − 5. Étirer après le décalage vers le bas donnerait 2(x − 3)² − 10.'},
    {q:'b) Combien vaut g(0) ?',lab:'g(0) =',ans:13,hint:'Remplace x par 0.',why:'2 · 9 − 5 = 13.'},
    {q:'c) Quel est le plus grand zéro de g ? (au centième)',lab:'x =',ans:4.58,tol:.011,hint:'2(x − 3)² = 5 donne (x − 3)² = 2,5.',why:'x − 3 = ±√2,5, donc x = 3 + √2,5 ≈ 4,58.'},
   ],
   sol:'Décaler de 3 à droite : (x − 3)². Étirer par 2 : 2(x − 3)². Descendre de 5 : g(x) = 2(x − 3)² − 5.<br>Le sommet est (3 ; −5) et g(0) = 13.<br>Zéros : (x − 3)² = 2,5, donc x = 3 ± √2,5, soit x ≈ 1,42 ou x ≈ 4,58.<br>L’ordre compte : un étirement vertical agit aussi sur les décalages verticaux faits avant lui.'},
  {kind:'Problème',h:'Composer et inverser',
   p:'On pose <i>f(x) = 2x + 1</i> et <i>g(x) = x²</i>. On compare <i>g∘f</i> (d’abord f, puis g) et <i>f∘g</i>, on cherche la réciproque de f, et on étudie la parité de <i>h(x) = g(f(x)) − g(f(−x))</i>.',
   parts:[
    {q:'a) Combien vaut (g∘f)(2) ?',ans:25,hint:'Calcule f(2), puis applique g.',why:'f(2) = 5, puis g(5) = 25.'},
    {q:'b) Combien vaut (f∘g)(2) ?',ans:9,hint:'Calcule g(2), puis applique f.',why:'g(2) = 4, puis f(4) = 9. L’ordre change le résultat.'},
    {q:'c) Pour quelles valeurs de x a-t-on (g∘f)(x) = (f∘g)(x) ?',opts:['Jamais','Pour tout x','x = 0 ou x = −2','x = 1 seulement'],ans:2,hint:'Résous (2x + 1)² = 2x² + 1.',why:'4x² + 4x + 1 = 2x² + 1 donne 2x² + 4x = 0, soit 2x(x + 2) = 0.'},
    {q:'d) Combien vaut f⁻¹(7) ?',ans:3,hint:'Cherche x tel que 2x + 1 = 7.',why:'f⁻¹(y) = (y − 1)/2, donc f⁻¹(7) = 3. Contrôle : f(3) = 7.'},
    {q:'e) La fonction h est…',opts:['paire','impaire','ni paire ni impaire','constante'],ans:1,hint:'Développe (2x + 1)² − (−2x + 1)².',why:'h(x) = (4x² + 4x + 1) − (4x² − 4x + 1) = 8x. Et h(−x) = −h(x) : h est impaire.'},
   ],
   sol:'(g∘f)(x) = (2x + 1)² et (f∘g)(x) = 2x² + 1. En 2 : 25 et 9.<br>Elles coïncident si 4x² + 4x + 1 = 2x² + 1, soit 2x(x + 2) = 0 : x = 0 ou x = −2.<br>Réciproque : y = 2x + 1 ⟺ x = (y − 1)/2, donc f⁻¹(7) = 3.<br>h(x) = (2x + 1)² − (1 − 2x)² = 8x, qui est impaire. Sans calcul : h(−x) = g(f(−x)) − g(f(x)) = −h(x).'},
 ]},

{id:'suites',br:'ana',lv:'gym',h:'Suites',p:'Arithmétiques, géométriques, et la somme de Gauss.',
 lessons:['Suites géométriques','Suites arithmétiques','Sommes de termes','Limite d’une suite'],
 steps:[
  {h:'Multiplier par q à chaque terme',p:'Une suite géométrique part de <i>u₀</i> et multiplie par la raison <i>q</i> à chaque étape : <i>uₙ = u₀·qⁿ</i>.',
   params:[{id:'q',l:'Raison q',min:.5,max:1.5,step:.05,v:.8}],
   draw:v=>{ const P=plane({x:[-0.7,10.7],y:[0,8],h:220,grid:false,lx:2,ly:2});
     for(let n=0;n<=10;n++){ const u=4*Math.pow(v.q,n); P.rect(n-.3,0,.6,Math.min(u,8),{fill:'var(--accent)',fo:.75,c:null}); } return P.svg(); },
   info:v=>v.q<1?`q < 1 : les termes se rapprochent de 0 (u₁₀ ≈ ${fmt(4*v.q**10)})`:v.q>1?`q > 1 : explosion (u₁₀ ≈ ${fmt(4*v.q**10)})`:'q = 1 : suite constante'},
  {h:'Suite arithmétique',p:'On ajoute toujours la même raison. Si <i>u₀ = 5</i> et la raison vaut 3, combien vaut <i>u₁₀</i>&nbsp;?',lab:'u₁₀ =',ans:35,why:'uₙ = u₀ + n·r = 5 + 10·3 = 35.'},
  {h:'L’astuce de Gauss',p:'Le jeune Gauss l’aurait trouvé en quelques secondes : 1 + 2 + 3 + … + 100 = ?',ans:5050,why:'On associe 1 + 100, 2 + 99, 3 + 98… On obtient 50 paires valant 101, soit 5 050.'},
  {kind:'Défi',h:'Limite',p:`Vers quoi tend (${F(1,2)})ⁿ quand n devient très grand&nbsp;?`,opts:['0',F(1,2),'1','+∞'],ans:0,why:'On divise par 2 à chaque fois : ½, ¼, ⅛… Les termes s’approchent de 0 autant qu’on veut.'},
  {kind:'Problème',h:'La tirelire qui grossit',
   p:'Tu économises 50 CHF la première semaine, puis 5 CHF de plus chaque semaine : 50, 55, 60… On note <i>uₙ</i> le montant versé la semaine <i>n</i> (avec u₁ = 50) et <i>Sₙ</i> le total après <i>n</i> semaines.',
   parts:[
    {q:'a) Combien verses-tu la 20e semaine ?',lab:'u₂₀ =',unit:'CHF',ans:145,hint:'uₙ = u₁ + (n − 1)·r.',why:'50 + 19 × 5 = 145 CHF.'},
    {q:'b) Quel est le total après 20 semaines ?',unit:'CHF',ans:1950,hint:'Somme = nombre de termes × (premier + dernier) ÷ 2.',why:'20 × (50 + 145) ÷ 2 = 1950 CHF.'},
    {q:'c) Après combien de semaines dépasses-tu 1000 CHF pour la première fois ?',ans:13,hint:'Sₙ = n(95 + 5n)/2. Teste n = 12 et n = 13, ou résous l’inéquation du 2e degré.',why:'S₁₂ = 12 × 155 ÷ 2 = 930 et S₁₃ = 13 × 160 ÷ 2 = 1040. C’est la 13e semaine.'},
   ],
   sol:'C’est une suite arithmétique de raison 5 : uₙ = 50 + 5(n − 1) = 45 + 5n, donc u₂₀ = 145.<br>Somme : Sₙ = n(u₁ + uₙ)/2 = n(95 + 5n)/2. S₂₀ = 1950 CHF.<br>Sₙ ≥ 1000 ⟺ n² + 19n − 400 ≥ 0 ⟺ n ≥ 12,64.<br>Le premier entier est 13 : S₁₃ = 1040 CHF.'},
  {kind:'Problème',h:'La balle qui rebondit',
   p:'On lâche une balle d’une hauteur de 2 m. À chaque rebond, elle remonte aux trois quarts de la hauteur précédente. On veut la hauteur des rebonds et la distance totale parcourue si elle rebondit indéfiniment.',
   params:[{id:'n',l:'Rebonds dessinés',min:1,max:10,v:3}],
   draw:v=>{ const P=plane({x:[-0.3,11],y:[-0.2,2.3],h:200,grid:false,lx:2,ly:1}); for(let k=0;k<=v.n;k++){ const hk=2*.75**k; P.rect(k-.3,0,.6,hk,{fill:k?'var(--accent)':'var(--spark)',fo:.7,c:null}); } return P.svg(); },
   info:v=>`hauteur après ${v.n} rebond${v.n>1?'s':''} : ${fmt(2*.75**v.n*100,1)} cm`,
   parts:[
    {q:'a) Quelle est la hauteur après le 3e rebond ? (au cm près)',unit:'cm',ans:84,tol:.6,hint:'hₙ = 2 · 0,75ⁿ mètres.',why:'2 × 0,75³ = 0,84375 m ≈ 84 cm.'},
    {q:'b) Après combien de rebonds la hauteur passe-t-elle sous 10 cm ?',ans:11,hint:'Résous 2 · 0,75ⁿ < 0,1 avec le logarithme.',why:'0,75ⁿ < 0,05 ⟺ n > ln 0,05 ÷ ln 0,75 ≈ 10,4. Au 11e rebond.'},
    {q:'c) Quelle distance totale la balle parcourt-elle (descentes et montées) ?',unit:'m',ans:14,tol:.001,hint:'La 1re chute fait 2 m. Ensuite chaque rebond est parcouru deux fois : 2 × (1,5 + 1,125 + …).',why:'Montées : 1,5 ÷ (1 − 0,75) = 6 m. Total : 2 + 2 × 6 = 14 m.'},
    {q:'d) Pourquoi une infinité de rebonds donne-t-elle une distance finie ?',opts:['Parce que la balle s’arrête vraiment après 11 rebonds','Parce que les termes tendent vers 0','Parce que la somme d’une suite géométrique de raison |q| < 1 converge','Parce que 0,75 < 1 implique que la somme vaut 1'],ans:2,hint:'Que des termes tendent vers 0 ne suffit pas toujours : pense à 1 + ½ + ⅓ + …',why:'Les sommes partielles d’une suite géométrique de raison 0,75 tendent vers u₀/(1 − q). Le seul fait que les termes tendent vers 0 ne suffirait pas.'},
   ],
   sol:'Hauteur après n rebonds : hₙ = 2 · 0,75ⁿ. h₃ ≈ 0,84 m.<br>hₙ < 0,1 ⟺ n > ln 0,05 ÷ ln 0,75 ≈ 10,4 : dès le 11e rebond.<br>Distance : 2 m de chute, puis chaque hauteur h₁, h₂, … est montée puis descendue.<br>h₁ + h₂ + … = 1,5 ÷ (1 − 0,75) = 6 m, donc la distance totale vaut 2 + 2 × 6 = 14 m.'},
 ]},

{id:'derivees',br:'ana',lv:'gym',h:'Dérivées',p:'La pente en un point, la vitesse instantanée.',
 lessons:['De la sécante à la tangente','Règles de dérivation','Étude de fonction','Optimisation'],
 steps:[
  {h:'Zoomer sur une pente',p:'La pente de la sécante entre <i>x₀</i> et <i>x₀ + h</i> s’approche de la pente de la tangente quand <i>h</i> devient petit. Cette limite, c’est la <b>dérivée</b>.',
   params:[{id:'x',l:'x₀',min:-2,max:2,step:.5,v:1},{id:'h',l:'h',min:.1,max:2,step:.1,v:1.5}],
   draw:v=>{ const f=x=>x*x/2, P=plane({x:[-3,3.5],y:[-1,5.5]}), m=(f(v.x+v.h)-f(v.x))/v.h;
     P.fn(f).fn(x=>f(v.x)+m*(x-v.x),{c:'var(--spark)',w:2.5}).fn(x=>f(v.x)+v.x*(x-v.x),{c:'var(--muted)',w:1.5,dash:true}).dot(v.x,f(v.x),{c:'var(--ink)',r:5}).dot(v.x+v.h,f(v.x+v.h),{r:5}); return P.svg(); },
   info:v=>`f(x) = x²/2 · pente de la sécante = ${fmt(v.x+v.h/2)} → quand h → 0 : f′(x₀) = ${fmt(v.x)}`},
  {h:'Règle de la puissance',p:'Quelle est la dérivée de <i>x³</i>&nbsp;?',opts:['3x²','x²','3x','x⁴/4'],ans:0,why:'(xⁿ)′ = n·xⁿ⁻¹. Pour n = 3 : 3x².'},
  {h:'Trouve la tangente horizontale',p:'Déplace le point sur <i>f(x) = x² − 4x + 1</i> jusqu’à ce que la tangente soit horizontale.',
   params:[{id:'x',l:'x',min:-1,max:5,step:.5,v:0}],
   draw:v=>{ const f=x=>x*x-4*x+1, m=2*v.x-4, P=plane({x:[-1.5,5.5],y:[-4,6],h:300,lab:2}); P.fn(f).fn(x=>f(v.x)+m*(x-v.x),{c:'var(--spark)',w:2.5}).dot(v.x,f(v.x),{c:'var(--ink)',r:5}); return P.svg(); },
   info:v=>`pente de la tangente : f′(${fmt(v.x)}) = ${fmt(2*v.x-4)}`,
   ok:v=>v.x===2,why:'f′(x) = 2x − 4 = 0 pour x = 2. C’est le minimum de la fonction.'},
  {kind:'Défi',h:'Calcule',p:'<i>f(x) = 5x²</i>. Combien vaut <i>f′(3)</i>&nbsp;?',lab:'f′(3) =',ans:30,why:'f′(x) = 10x, donc f′(3) = 30.'},
  {kind:'Problème',h:'Le bénéfice maximal',
   p:'Une coopérative vend <i>q</i> tonnes de fromage par mois. Son bénéfice (en milliers de CHF) vaut <i>B(q) = −2q² + 120q − 1000</i>, pour q entre 0 et 60. On cherche la production qui rapporte le plus et on interprète la dérivée.',
   parts:[
    {q:'a) Pour quelle production B′(q) s’annule-t-elle ?',lab:'q =',unit:'t',ans:30,hint:'Dérive terme à terme.',why:'B′(q) = −4q + 120 = 0 pour q = 30 t.'},
    {q:'b) Quel est le bénéfice maximal ? (en milliers de CHF)',ans:800,hint:'Calcule B(30). Vérifie que B′ change de signe.',why:'B(30) = −1800 + 3600 − 1000 = 800, soit 800 000 CHF. B′ > 0 avant 30 et B′ < 0 après.'},
    {q:'c) Combien vaut B′(20) ?',lab:'B′(20) =',ans:40,hint:'Remplace q par 20 dans B′.',why:'B′(20) = −80 + 120 = 40.'},
    {q:'d) Que signifie B′(20) = 40 ?',opts:['Le bénéfice vaut 40 000 CHF pour 20 t','Vers 20 t, une tonne de plus rapporte environ 40 000 CHF de plus','Il faut produire 40 t','Le bénéfice baisse de 40 000 CHF par tonne'],ans:1,hint:'La dérivée est un taux de variation : unités de B par unité de q.',why:'B′(20) est la pente de la tangente : près de q = 20, B augmente d’environ 40 milliers de CHF par tonne supplémentaire.'},
   ],
   sol:'B′(q) = −4q + 120. B′ est positive pour q < 30 et négative pour q > 30 : B est maximal en q = 30.<br>B(30) = −2 · 900 + 3600 − 1000 = 800, soit 800 000 CHF.<br>B′(20) = 40 : vers 20 t, chaque tonne supplémentaire ajoute environ 40 000 CHF de bénéfice.<br>Au maximum, ce gain marginal tombe à 0.'},
  {kind:'Problème',h:'La canette la plus économique',
   p:'Une canette cylindrique doit contenir 330 cm³. Pour économiser le métal, on veut minimiser sa surface totale (fond, couvercle et côté). Avec un rayon <i>r</i>, la hauteur vaut <i>h = 330/(πr²)</i> et la surface vaut <i>S(r) = 2πr² + 660/r</i>.',
   params:[{id:'r',l:'Rayon r',min:2,max:6,step:.25,v:2.5,u:' cm'}],
   draw:v=>{ const S=r=>2*Math.PI*r*r+660/r, P=plane({x:[1.5,6.5],y:[200,400],w:300,h:200,grid:false,axes:false}); P.fn(S,{from:1.6,to:6.4}).dot(v.r,S(v.r)).seg(1.5,200,6.5,200,{c:'var(--muted)',w:1.5}); for(let x=2;x<=6;x++) P.text(x,200,String(x),{a:'middle',dy:-4,s:10,c:'var(--muted)'}); return P.svg(); },
   info:v=>`r = ${fmt(v.r)} cm · h ≈ ${fmt(330/(Math.PI*v.r*v.r))} cm · S ≈ ${fmt(2*Math.PI*v.r*v.r+660/v.r,1)} cm²`,
   parts:[
    {q:'a) Quelle est la hauteur pour r = 3 cm ? (au centième)',unit:'cm',ans:11.67,tol:.011,hint:'h = 330/(πr²).',why:'h = 330 ÷ (9π) ≈ 11,67 cm.'},
    {q:'b) Pour quel rayon S′(r) s’annule-t-il ? (au centième)',lab:'r =',unit:'cm',ans:3.74,tol:.011,hint:'S′(r) = 4πr − 660/r². Résous S′(r) = 0.',why:'4πr³ = 660, donc r³ = 330/(2π) et r ≈ 3,74 cm.'},
    {q:'c) À l’optimum, combien vaut le rapport h/r ?',lab:'h/r =',ans:2,tol:.001,hint:'Remplace 330 par 2πr³ dans h = 330/(πr²).',why:'h = 2πr³/(πr²) = 2r. La hauteur égale le diamètre.'},
    {q:'d) Quelle est la surface minimale ? (au cm² près)',unit:'cm²',ans:264,tol:1,hint:'À l’optimum, 660/r = 4πr², donc S = 6πr².',why:'S = 6π · 3,745² ≈ 264 cm².'},
   ],
   sol:'S(r) = 2πr² + 2πrh avec h = 330/(πr²), donc S(r) = 2πr² + 660/r.<br>S′(r) = 4πr − 660/r² = 0 ⟺ r³ = 330/(2π) ⟺ r ≈ 3,74 cm.<br>S′ < 0 avant et S′ > 0 après : c’est un minimum.<br>Alors h = 330/(πr²) = 2r ≈ 7,49 cm et S = 6πr² ≈ 264 cm².<br>La canette optimale est aussi haute que large. Les vraies canettes sont plus hautes, pour la prise en main.'},
 ]},

{id:'integrales',br:'ana',lv:'gym',h:'Intégrales',p:'Additionner une infinité de petits rectangles.',
 lessons:['Aire sous la courbe','Primitives','Théorème fondamental','Volumes de révolution'],
 steps:[
  {h:'Des rectangles de plus en plus fins',p:'Pour mesurer l’aire sous <i>y = x²</i> entre 0 et 2, on l’approche par des rectangles. Plus ils sont nombreux, plus l’approximation est bonne.',
   params:[{id:'n',l:'Nombre de rectangles',min:1,max:40,v:4}],
   draw:v=>{ const P=plane({x:[-0.3,2.4],y:[-0.4,4.4],h:300,lx:1,ly:1}), dx=2/v.n;
     for(let i=0;i<v.n;i++){ const x=i*dx; P.rect(x,0,dx,x*x,{fill:'var(--spark)',fo:.5,c:'var(--ink)',w:v.n>20?.5:1}); } P.fn(x=>x*x,{from:0}); return P.svg(); },
   info:v=>{ let s=0; const dx=2/v.n; for(let i=0;i<v.n;i++) s+=(i*dx)**2*dx; return `Somme ≈ ${fmt(s,3)} · aire exacte = 8/3 ≈ 2,667`; }},
  {h:'Une aire connue',p:'Combien vaut <i>∫₀³ 2x dx</i>&nbsp;?',
   fig:(()=>{ const P=plane({x:[-0.5,4],y:[-0.5,7],h:240,lx:1,ly:2}); P.area(x=>2*x,0,3,{fill:'var(--math)'}).fn(x=>2*x); return P.svg(); })(),
   ans:9,why:'C’est l’aire d’un triangle de base 3 et de hauteur 6 : 3 × 6 ÷ 2 = 9.'},
  {h:'Primitive',p:'Une primitive de <i>3x²</i> est…',opts:['6x','x³ + C','3x³','x³/3'],ans:1,why:'On cherche F avec F′ = 3x². (x³)′ = 3x², donc F(x) = x³ + C.'},
  {kind:'Défi',h:'Le calcul exact',p:'Combien vaut <i>∫₀¹ x² dx</i>&nbsp;? (fraction ou décimale)',ans:1/3,tol:.005,why:'Une primitive est x³/3. On calcule 1³/3 − 0 = 1/3 ≈ 0,333.'},
  {kind:'Problème',h:'La distance de freinage',
   p:'Une voiture roule à 20 m/s (72 km/h) et freine. Sa vitesse vaut <i>v(t) = 20 − 4t</i> (en m/s) jusqu’à l’arrêt. La distance parcourue entre deux instants est l’intégrale de la vitesse.',
   fig:(()=>{ const P=plane({x:[-0.5,6],y:[-2,22],w:300,h:220,lx:1,ly:5,grid:false}); P.area(t=>20-4*t,0,5,{fill:'var(--math)'}).fn(t=>20-4*t,{from:0,to:5}); P.text(5.8,0,'t',{dy:-6,c:'var(--muted)'}); return P.svg(); })(),
   parts:[
    {q:'a) Combien de temps dure le freinage ?',unit:'s',ans:5,hint:'Résous v(t) = 0.',why:'20 − 4t = 0 donne t = 5 s.'},
    {q:'b) Quelle est la distance de freinage ?',unit:'m',ans:50,hint:'Calcule ∫₀⁵ (20 − 4t) dt, ou l’aire du triangle.',why:'[20t − 2t²]₀⁵ = 100 − 50 = 50 m.'},
    {q:'c) Quelle distance la voiture parcourt-elle pendant la première seconde ?',unit:'m',ans:18,hint:'∫₀¹ (20 − 4t) dt.',why:'20 − 2 = 18 m. La voiture parcourt plus d’un tiers de la distance dans la première seconde.'},
    {q:'d) À quel instant a-t-elle parcouru la moitié de la distance de freinage ? (au centième)',lab:'t =',unit:'s',ans:1.46,tol:.011,hint:'Résous 20t − 2t² = 25 et garde la solution entre 0 et 5.',why:'2t² − 20t + 25 = 0 donne t = (20 − √200)/4 ≈ 1,46 s.'},
   ],
   sol:'Arrêt : v(t) = 0 en t = 5 s. Une primitive de v est d(t) = 20t − 2t².<br>Distance : d(5) − d(0) = 50 m (l’aire du triangle 5 × 20 ÷ 2).<br>Première seconde : d(1) = 18 m.<br>Mi-distance : 20t − 2t² = 25, soit t = (20 − √200)/4 ≈ 1,46 s. La moitié de la distance est faite en moins d’un tiers du temps.'},
  {kind:'Problème',h:'Entre la droite et la parabole',
   p:'On étudie le domaine compris entre la droite <i>y = 2x</i> et la parabole <i>y = x²</i>. On calcule son aire, la valeur moyenne de l’écart entre les deux courbes, puis le volume obtenu en faisant tourner le domaine autour de l’axe des x.',
   fig:(()=>{ const P=plane({x:[-0.5,2.8],y:[-0.5,5],w:260,lx:1,ly:1}); const pts=[]; for(let i=0;i<=40;i++){ const x=2*i/40; pts.push([x,x*x]); } for(let i=40;i>=0;i--){ const x=2*i/40; pts.push([x,2*x]); }
     P.poly(pts,{fill:'var(--spark)',fo:.4,c:null}).fn(x=>x*x,{c:'var(--math)'}).fn(x=>2*x,{c:'var(--accent)'}); return P.svg(); })(),
   parts:[
    {q:'a) Les courbes se coupent en x = 0 et en une autre valeur. Laquelle ?',lab:'x =',ans:2,hint:'Résous x² = 2x.',why:'x² − 2x = x(x − 2) = 0, donc x = 0 ou x = 2.'},
    {q:'b) Quelle est l’aire du domaine ? (fraction ou décimale)',ans:4/3,tol:.005,hint:'Entre 0 et 2, la droite est au-dessus : intègre 2x − x².',why:'∫₀² (2x − x²) dx = [x² − x³/3]₀² = 4 − 8/3 = 4/3.'},
    {q:'c) Quelle est la valeur moyenne de 2x − x² sur [0 ; 2] ?',ans:2/3,tol:.005,hint:'Valeur moyenne = intégrale ÷ longueur de l’intervalle.',why:'(4/3) ÷ 2 = 2/3.'},
    {q:'d) Quel volume engendre le domaine en tournant autour de l’axe des x ? (au centième)',ans:13.4,tol:.011,hint:'Volume = π∫(R² − r²) dx, avec R = 2x et r = x².',why:'π∫₀² (4x² − x⁴) dx = π(32/3 − 32/5) = 64π/15 ≈ 13,40.'},
   ],
   sol:'Intersections : x² = 2x, donc x = 0 ou x = 2. Sur [0 ; 2], 2x ≥ x².<br>Aire : ∫₀² (2x − x²) dx = 4 − 8/3 = 4/3. Valeur moyenne : 4/3 ÷ 2 = 2/3.<br>Volume : chaque tranche est un anneau de rayons 2x et x², d’aire π(4x² − x⁴).<br>V = π[4x³/3 − x⁵/5]₀² = π(32/3 − 32/5) = 64π/15 ≈ 13,40.<br>Piège : π∫(2x − x²)² dx ne donne pas le bon volume.'},
 ]},

{id:'trigo',br:'geo',lv:'gym',h:'Trigonométrie',p:'Le cercle trigonométrique, sinus et cosinus.',
 lessons:['Le cercle trigonométrique','Triangles rectangles','Lois du sinus et du cosinus','Fonctions trigonométriques'],
 steps:[
  {h:'Cosinus et sinus sur le cercle',p:'Sur un cercle de rayon 1, le point d’angle θ a pour coordonnées <b>(cos θ ; sin θ)</b>.',
   params:[{id:'t',l:'Angle θ',min:0,max:360,step:5,v:30,u:'°'}],
   draw:v=>{ const c=Math.cos(rad(v.t)),s=Math.sin(rad(v.t)),P=plane({x:[-1.4,1.4],y:[-1.4,1.4],step:.5,lab:1});
     P.circ(0,0,1,{c:'var(--ink)',w:2}).seg(0,0,c,s,{c:'var(--ink)',w:2.5}).seg(0,0,c,0,{c:'var(--math)',w:5}).seg(c,0,c,s,{c:'var(--spark)',w:5}).dot(c,s,{c:'var(--accent)'}); return P.svg(); },
   info:v=>`<span style="color:var(--math)">cos θ ≈ ${fmt(Math.cos(rad(v.t)),3)}</span> · <span style="color:color-mix(in srgb,var(--spark) 70%,var(--ink))">sin θ ≈ ${fmt(Math.sin(rad(v.t)),3)}</span>`},
  {h:'Une valeur à connaître',p:'Combien vaut <i>sin 30°</i>&nbsp;?',opts:[F(1,2),F('√3',2),F('√2',2),'1'],ans:0,why:'Un triangle équilatéral coupé en deux donne un angle de 30° : le côté opposé vaut la moitié de l’hypoténuse.'},
  {h:'Trouve l’angle',p:`Règle θ entre 0° et 180° pour que <b>cos θ = −${F(1,2)}</b>.`,
   params:[{id:'t',l:'Angle θ',min:0,max:180,step:5,v:60,u:'°'}],
   draw:v=>{ const c=Math.cos(rad(v.t)),s=Math.sin(rad(v.t)),P=plane({x:[-1.4,1.4],y:[-1.4,1.4],step:.5,lab:1});
     P.circ(0,0,1,{c:'var(--ink)',w:2}).seg(-.5,-1.4,-.5,1.4,{c:'var(--bad)',w:1.5,dash:true}).seg(0,0,c,s,{c:'var(--ink)',w:2.5}).seg(0,0,c,0,{c:'var(--math)',w:5}).dot(c,s,{c:'var(--accent)'}); return P.svg(); },
   info:v=>`cos ${v.t}° ≈ ${fmt(Math.cos(rad(v.t)),3)}`,ok:v=>v.t===120,why:'cos 60° = ½, et le symétrique par rapport à l’axe vertical donne cos 120° = −½.'},
  {kind:'Défi',h:'La rampe',p:'Une rampe de 10 m de long monte avec un angle de 30°. De quelle hauteur monte-t-elle&nbsp;?',unit:'m',ans:5,why:'hauteur = 10 × sin 30° = 10 × ½ = 5 m.'},
  {kind:'Problème',h:'L’échelle des pompiers',
   p:'Une échelle de 6 m est posée contre une façade. Pour la sécurité, l’angle avec le sol doit rester entre 65° et 75°. On la pose d’abord à 70°.',
   parts:[
    {q:'a) À quelle hauteur touche-t-elle la façade ? (au centième)',unit:'m',ans:5.64,tol:.011,hint:'La hauteur est le côté opposé à l’angle.',why:'6 × sin 70° ≈ 5,64 m.'},
    {q:'b) À quelle distance de la façade est son pied ? (au centième)',unit:'m',ans:2.05,tol:.011,hint:'Côté adjacent = hypoténuse × cos.',why:'6 × cos 70° ≈ 2,05 m.'},
    {q:'c) Il faut atteindre 5,8 m. Quel angle faut-il ? (au dixième de degré)',unit:'°',ans:75.2,tol:.051,hint:'sin α = 5,8 ÷ 6.',why:'α = arcsin(5,8 ÷ 6) ≈ 75,2°.'},
    {q:'d) Peut-on atteindre 5,8 m avec cette échelle en respectant la règle ?',opts:['Oui, sans problème','Non : il faudrait un angle supérieur à 75°','Oui, à condition de placer le pied à plus de 2 m','Non : l’échelle est plus courte que 5,8 m'],ans:1,hint:'Compare l’angle trouvé avec 75°.',why:'75,2° dépasse la limite de 75°. À 75°, l’échelle n’atteint que 6 × sin 75° ≈ 5,796 m, juste sous 5,8 m.'},
   ],
   sol:'Hauteur : 6 sin 70° ≈ 5,64 m. Pied : 6 cos 70° ≈ 2,05 m.<br>Pour 5,8 m : sin α = 5,8/6 ≈ 0,967, donc α ≈ 75,2°.<br>C’est au-delà de 75° : l’échelle serait trop raide.<br>À 75°, elle atteint 6 sin 75° ≈ 5,796 m. Il manque 4 mm : il faut une échelle plus longue.'},
  {kind:'Problème',h:'La hauteur d’une tour inaccessible',
   p:'Depuis un point A, on voit le sommet S d’une tour sous un angle de 35° au-dessus de l’horizontale. On avance de 40 m en direction de la tour jusqu’au point B : on voit alors le sommet sous 50°. On ne peut pas atteindre le pied de la tour.',
   fig:(()=>{ const P=plane({x:[-5,105],y:[-8,75],w:300,grid:false,axes:false}); P.seg(-5,0,105,0,{c:'var(--muted)',w:2}).seg(97,0,97,67.9,{c:'var(--sci)',w:6}).seg(0,0,97,67.9,{c:'var(--spark)',w:2,dash:true}).seg(40,0,97,67.9,{c:'var(--accent)',w:2,dash:true});
     P.dot(0,0,{l:'A',dy:16}).dot(40,0,{l:'B',dy:16}).dot(97,67.9,{l:'S',dx:-18}).text(20,0,'40 m',{a:'middle',dy:16,s:11}).text(9,0,'35°',{dy:-5,s:11}).text(48,0,'50°',{dy:-5,s:11}); return P.svg(); })(),
   parts:[
    {q:'a) Quel est l’angle en S du triangle ABS ?',unit:'°',ans:15,hint:'L’angle en B du triangle ABS vaut 180° − 50°.',why:'180° − 35° − 130° = 15°.'},
    {q:'b) Quelle est la distance BS ? (au centième)',unit:'m',ans:88.65,tol:.02,hint:'Loi du sinus : BS ÷ sin 35° = AB ÷ sin 15°.',why:'BS = 40 sin 35° ÷ sin 15° ≈ 88,65 m.'},
    {q:'c) Quelle est la hauteur de la tour ? (au dixième)',unit:'m',ans:67.9,tol:.06,hint:'Dans le triangle rectangle formé par B, le pied de la tour et S, l’angle en B vaut 50°.',why:'h = BS sin 50° ≈ 67,9 m.'},
    {q:'d) À quelle distance de la tour est le point B ? (au dixième)',unit:'m',ans:57,tol:.06,hint:'Côté adjacent à l’angle de 50°.',why:'BS cos 50° ≈ 57,0 m.'},
   ],
   sol:'Dans le triangle ABS : angle en A = 35°, angle en B = 180° − 50° = 130°, donc angle en S = 15°.<br>Loi du sinus : BS = AB · sin 35° / sin 15° = 40 · 0,5736 / 0,2588 ≈ 88,65 m.<br>Dans le triangle rectangle au pied de la tour : h = BS · sin 50° ≈ 67,9 m, et la distance de B au pied vaut BS · cos 50° ≈ 57,0 m.<br>Contrôle : depuis A, tan 35° · (57,0 + 40) ≈ 67,9 m.'},
 ]},

{id:'vecteurs',br:'geo',lv:'gym',h:'Vecteurs du plan',p:'Flèches, sommes et produit scalaire.',
 lessons:['Additionner des vecteurs','Norme d’un vecteur','Produit scalaire','Droites et vecteurs directeurs'],
 steps:[
  {h:'Mettre les flèches bout à bout',p:'Pour additionner <b>u</b> et <b>v</b>, on place <b>v</b> au bout de <b>u</b>. La somme va du départ à l’arrivée.',
   params:[{id:'ux',l:'u, composante x',min:-3,max:3,v:3},{id:'uy',l:'u, composante y',min:-3,max:3,v:1},{id:'vx',l:'v, composante x',min:-3,max:3,v:1},{id:'vy',l:'v, composante y',min:-3,max:3,v:2}],
   draw:v=>{ const P=plane({x:[-6,6],y:[-6,6],lab:2}); P.arrow(0,0,v.ux,v.uy,{c:'var(--math)'}).arrow(v.ux,v.uy,v.ux+v.vx,v.uy+v.vy,{c:'var(--spark)'}).arrow(0,0,v.ux+v.vx,v.uy+v.vy,{c:'var(--accent)',w:4}); return P.svg(); },
   info:v=>`<span style="color:var(--math)">u (${v.ux} ; ${v.uy})</span> + v (${v.vx} ; ${v.vy}) = <b style="color:var(--accent)">(${v.ux+v.vx} ; ${v.uy+v.vy})</b>`},
  {h:'Produit scalaire',p:'Calcule <b>(3 ; 4) · (2 ; −1)</b>.',ans:2,why:'On multiplie composante par composante et on additionne : 3·2 + 4·(−1) = 6 − 4 = 2.'},
  {h:'Que signifie un produit nul&nbsp;?',p:'Si <b>u · v = 0</b> avec deux vecteurs non nuls, alors…',opts:['u et v sont perpendiculaires','u et v sont parallèles','u = v','u + v = 0'],ans:0,why:'u · v = ‖u‖‖v‖ cos θ. Il est nul quand cos θ = 0, donc θ = 90°.'},
  {kind:'Défi',h:'Norme',p:'Quelle est la norme (longueur) du vecteur <b>(5 ; 12)</b>&nbsp;?',ans:13,why:'‖u‖ = √(5² + 12²) = √169 = 13. C’est Pythagore.'},
  {kind:'Problème',h:'Traverser avec le courant',
   p:'Un bateau avance à 8 km/h par rapport à l’eau. Un courant le pousse vers le sud à 3 km/h. On place l’est sur l’axe x et le nord sur l’axe y : le courant est le vecteur (0 ; −3).',
   parts:[
    {q:'a) Le bateau vise plein est : sa vitesse propre est (8 ; 0). Quelle est sa vitesse réelle (norme, au centième) ?',unit:'km/h',ans:8.54,tol:.011,hint:'Additionne les vecteurs, puis calcule la norme.',why:'(8 ; 0) + (0 ; −3) = (8 ; −3), de norme √73 ≈ 8,54 km/h.'},
    {q:'b) De quel angle dévie-t-il vers le sud ? (au dixième de degré)',unit:'°',ans:20.6,tol:.051,hint:'tan α = 3 ÷ 8.',why:'α = arctan(3/8) ≈ 20,6°.'},
    {q:'c) Pour aller droit vers l’est, le pilote vise (a ; 3) avec une norme toujours égale à 8. Quelle est alors sa vitesse réelle ? (au centième)',unit:'km/h',ans:7.42,tol:.011,hint:'a² + 3² = 8², et la vitesse réelle vaut (a ; 0).',why:'a = √(64 − 9) = √55 ≈ 7,42 km/h.'},
   ],
   sol:'Vitesse réelle = vitesse propre + courant.<br>Cap plein est : (8 ; −3), norme √73 ≈ 8,54 km/h, déviation arctan(3/8) ≈ 20,6° vers le sud.<br>Pour compenser, il faut une composante nord de 3 : (a ; 3) + (0 ; −3) = (a ; 0) avec a² + 9 = 64.<br>a = √55 ≈ 7,42 km/h : on va droit, mais moins vite.'},
  {kind:'Problème',h:'Un triangle par les vecteurs',
   p:'On donne A(0 ; 0), B(4 ; 1) et C(1 ; 3). Sans rapporteur ni règle, on veut l’angle en A, l’aire du triangle et la distance de C à la droite (AB), uniquement avec des calculs de vecteurs.',
   fig:(()=>{ const P=plane({x:[-1,5],y:[-1,4],lab:1}); P.poly([[0,0],[4,1],[1,3]],{fill:'var(--sci)',fo:.2,c:'var(--ink)',w:2}).arrow(0,0,4,1,{c:'var(--math)'}).arrow(0,0,1,3,{c:'var(--spark)'}).dot(0,0,{l:'A',dx:-16}).dot(4,1,{l:'B'}).dot(1,3,{l:'C'}); return P.svg(); })(),
   parts:[
    {q:'a) Combien vaut le produit scalaire AB · AC ?',ans:7,hint:'AB = (4 ; 1) et AC = (1 ; 3).',why:'4 · 1 + 1 · 3 = 7.'},
    {q:'b) Quel est l’angle en A ? (au dixième de degré)',unit:'°',ans:57.5,tol:.051,hint:'cos θ = AB · AC ÷ (‖AB‖ · ‖AC‖).',why:'cos θ = 7 ÷ (√17 · √10) ≈ 0,537, donc θ ≈ 57,5°.'},
    {q:'c) Quelle est l’aire du triangle ?',ans:5.5,tol:.001,hint:'Aire = ½ |x₁y₂ − x₂y₁| avec les composantes de AB et AC.',why:'½ |4 · 3 − 1 · 1| = 11/2 = 5,5.'},
    {q:'d) Quelle est la distance de C à la droite (AB) ? (au centième)',ans:2.67,tol:.011,hint:'Aire = ½ · ‖AB‖ · hauteur.',why:'h = 2 · 5,5 ÷ √17 = 11/√17 ≈ 2,67.'},
   ],
   sol:'AB = (4 ; 1), AC = (1 ; 3), AB · AC = 7, ‖AB‖ = √17, ‖AC‖ = √10.<br>cos Â = 7/√170 ≈ 0,537, donc Â ≈ 57,5°.<br>Aire = ½ |det(AB, AC)| = ½ |12 − 1| = 5,5.<br>La hauteur issue de C vaut 2 · Aire / ‖AB‖ = 11/√17 ≈ 2,67.<br>Contrôle : ½ ‖AB‖‖AC‖ sin Â = ½ · √170 · sin 57,5° ≈ 5,5.'},
 ]},

{id:'analytique',br:'geo',lv:'gym',h:'Géométrie analytique',p:'Cercles et droites en équations.',
 lessons:['Équation d’un cercle','Droites et intersections','Distance point-droite','Les coniques'],
 steps:[
  {h:'Le cercle en équation',p:'Le cercle de centre (h ; k) et de rayon r regroupe les points à distance r du centre : <i>(x − h)² + (y − k)² = r²</i>.',
   params:[{id:'h',l:'h',min:-3,max:3,v:1},{id:'k',l:'k',min:-3,max:3,v:-1},{id:'r',l:'r',min:1,max:5,step:.5,v:2}],
   draw:v=>{ const P=plane({x:[-6,6],y:[-6,6],lab:2}); P.circ(v.h,v.k,v.r,{w:3.5}).dot(v.h,v.k,{r:5,c:'var(--ink)'}).seg(v.h,v.k,v.h+v.r,v.k,{c:'var(--spark)',w:2.5,dash:true}); return P.svg(); },
   info:v=>`(x ${v.h<0?'+':'−'} ${Math.abs(v.h)})² + (y ${v.k<0?'+':'−'} ${Math.abs(v.k)})² = ${fmt(v.r*v.r)}`},
  {h:'Passer par l’origine',p:'Le cercle a pour centre (3 ; 4). Règle son rayon pour qu’il passe par l’origine.',
   params:[{id:'r',l:'Rayon r',min:1,max:8,step:.5,v:2}],
   draw:v=>{ const P=plane({x:[-5,10],y:[-4,11],w:300,lab:2}); P.circ(3,4,v.r,{w:3.5}).dot(3,4,{r:5,c:'var(--ink)'}).dot(0,0,{l:'O'}); return P.svg(); },
   ok:v=>v.r===5,why:'Le rayon est la distance du centre à l’origine : √(3² + 4²) = 5.'},
  {h:'Retrouver le centre',p:'Quel est le centre du cercle <i>x² + y² − 6x + 2y = 0</i>&nbsp;?',opts:['(3 ; −1)','(−3 ; 1)','(6 ; −2)','(−6 ; 2)'],ans:0,why:'On complète les carrés : (x − 3)² + (y + 1)² = 10. Centre (3 ; −1), rayon √10.'},
  {kind:'Défi',h:'Distance',p:'Quelle est la distance entre les points (1 ; 2) et (4 ; 6)&nbsp;?',ans:5,why:'√((4 − 1)² + (6 − 2)²) = √(9 + 16) = 5.'},
  {kind:'Problème',h:'La zone de couverture',
   p:'Une antenne placée en (2 ; 3) (en km) couvre tous les points à moins de 5 km. Une maison est en M(6 ; 6). Une route rectiligne suit l’axe des x. On veut savoir si la maison capte, et sur quelle longueur la route est couverte.',
   fig:(()=>{ const P=plane({x:[-4,9],y:[-3,9],w:300,lab:2}); P.circ(2,3,5,{fill:'var(--sci)',fo:.15,w:2.5}).dot(2,3,{c:'var(--ink)',r:5}).dot(6,6,{l:'M'}).seg(-4,0,9,0,{c:'var(--spark)',w:4}); return P.svg(); })(),
   parts:[
    {q:'a) Quelle est l’équation du bord de la zone ?',opts:['(x + 2)² + (y + 3)² = 25','(x − 2)² + (y − 3)² = 5','(x − 2)² + (y − 3)² = 25','x² + y² = 25'],ans:2,hint:'Centre (h ; k), rayon r : (x − h)² + (y − k)² = r².',why:'Centre (2 ; 3), rayon 5 : (x − 2)² + (y − 3)² = 25.'},
    {q:'b) Où se trouve la maison M ?',opts:['Nettement dans la zone','Exactement sur le bord','Hors de la zone','On ne peut pas savoir'],ans:1,hint:'Calcule la distance de M au centre.',why:'√((6 − 2)² + (6 − 3)²) = √25 = 5 : M est pile sur le bord.'},
    {q:'c) Sur quelle longueur la route y = 0 est-elle couverte ?',unit:'km',ans:8,hint:'Remplace y par 0 dans l’équation et résous en x.',why:'(x − 2)² + 9 = 25, donc (x − 2)² = 16 et x = −2 ou x = 6. Longueur : 8 km.'},
   ],
   sol:'Bord de la zone : (x − 2)² + (y − 3)² = 25.<br>Pour M : (6 − 2)² + (6 − 3)² = 16 + 9 = 25. M est exactement sur le bord.<br>Route : y = 0 donne (x − 2)² = 16, donc x = −2 ou x = 6.<br>La route est couverte entre ces deux points, sur 8 km. On peut aussi le voir avec Pythagore : demi-corde √(25 − 9) = 4.'},
  {kind:'Problème',h:'Une droite qui frôle le cercle',
   p:'On donne le cercle <i>x² + y² − 4x − 6y + 4 = 0</i> et la droite <i>d : 3x + 4y − 3 = 0</i>. On veut savoir si d coupe le cercle, le touche ou passe à côté, puis trouver le point de contact s’il existe.',
   fig:(()=>{ const P=plane({x:[-2,6],y:[-1.5,7],w:280,lab:2}); P.circ(2,3,3,{w:3}).fn(x=>(3-3*x)/4,{c:'var(--spark)'}).dot(2,3,{c:'var(--ink)',r:5}).dot(.2,.6,{r:5}); return P.svg(); })(),
   parts:[
    {q:'a) Quel est le rayon du cercle ?',lab:'r =',ans:3,hint:'Complète les carrés : x² − 4x = (x − 2)² − 4.',why:'(x − 2)² + (y − 3)² = 4 + 9 − 4 = 9, donc r = 3 et le centre est (2 ; 3).'},
    {q:'b) Quelle est la distance du centre à la droite d ?',ans:3,tol:.001,hint:'Distance de (x₀ ; y₀) à ax + by + c = 0 : |ax₀ + by₀ + c| ÷ √(a² + b²).',why:'|3·2 + 4·3 − 3| ÷ 5 = 15 ÷ 5 = 3.'},
    {q:'c) Que conclut-on ?',opts:['d coupe le cercle en deux points','d est tangente au cercle','d ne touche pas le cercle','d passe par le centre'],ans:1,hint:'Compare la distance au rayon.',why:'La distance égale le rayon : d touche le cercle en un seul point.'},
    {q:'d) Quelle est l’abscisse du point de contact ?',lab:'x =',ans:.2,tol:.001,hint:'Pars du centre et va de 3 unités dans la direction de −(3 ; 4)/5, le vecteur normal unitaire tourné vers d.',why:'(2 ; 3) − 3 · (3 ; 4)/5 = (0,2 ; 0,6). Contrôle : 0,6 + 2,4 − 3 = 0.'},
   ],
   sol:'En complétant les carrés : (x − 2)² + (y − 3)² = 9. Centre Ω(2 ; 3), rayon 3.<br>Distance de Ω à d : |6 + 12 − 3| / √(9 + 16) = 15/5 = 3 = r. La droite est tangente.<br>Le point de contact est le pied de la perpendiculaire issue de Ω. Le vecteur (3 ; 4) est normal à d, et 3·2 + 4·3 − 3 > 0, donc on recule dans cette direction :<br>T = (2 ; 3) − 3 · (0,6 ; 0,8) = (0,2 ; 0,6).<br>Contrôle : T ∈ d et ΩT = √(1,8² + 2,4²) = 3.'},
 ]},

/* ================= UNIVERSITÉ ================= */
{id:'complexes',br:'alg',lv:'uni',h:'Nombres complexes',p:'Le plan complexe, rotations et racines de l’unité.',
 lessons:['Le plan complexe','Forme exponentielle','Racines de l’unité','Polynômes et théorème fondamental'],
 steps:[
  {h:'Un nombre, un point',p:'Le nombre <i>z = a + bi</i> est le point (a ; b). Sa distance à 0 est le <b>module</b> |z|, son angle est l’<b>argument</b>.',
   params:[{id:'a',l:'Partie réelle a',min:-4,max:4,step:.5,v:3},{id:'b',l:'Partie imaginaire b',min:-4,max:4,step:.5,v:2}],
   draw:v=>{ const P=plane({x:[-5,5],y:[-5,5],lab:2}); P.arrow(0,0,v.a,v.b).seg(v.a,0,v.a,v.b,{c:'var(--muted)',w:1.5,dash:true}).dot(v.a,v.b,{l:'z'}).text(4.9,0,'Re',{a:'end',dy:-6,c:'var(--muted)'}).text(0,4.8,'Im',{dx:6,dy:8,c:'var(--muted)'}); return P.svg(); },
   info:v=>`|z| = ${fmt(Math.hypot(v.a,v.b))} · arg z ≈ ${fmt(Math.atan2(v.b,v.a)*180/Math.PI,1)}°`},
  {h:'Multiplier par i, c’est tourner',p:'Multiplier par <i>i</i> fait tourner le point de 90° autour de 0. Deux fois de suite : 180°, d’où <i>i² = −1</i>.',
   params:[{id:'a',l:'a',min:-4,max:4,step:.5,v:3},{id:'b',l:'b',min:-4,max:4,step:.5,v:1}],
   draw:v=>{ const P=plane({x:[-5,5],y:[-5,5],lab:2}); P.arrow(0,0,v.a,v.b).arrow(0,0,-v.b,v.a,{c:'var(--spark)'}).arrow(0,0,-v.a,-v.b,{c:'var(--math)',dash:true,w:2}).dot(v.a,v.b,{l:'z',r:4}).dot(-v.b,v.a,{l:'iz',r:4}).dot(-v.a,-v.b,{l:'i²z = −z',r:4,c:'var(--math)'}); return P.svg(); }},
  {h:'Calcule',p:'<i>(1 + i)² = ?</i>',opts:['2i','2','0','1 + 2i'],ans:0,why:'(1 + i)² = 1 + 2i + i² = 1 + 2i − 1 = 2i.'},
  {kind:'Défi',h:'Racine cubique de l’unité',p:'Place le point <i>e^{iθ}</i> sur le cercle pour que <i>z³ = 1</i>, avec <i>z ≠ 1</i>.',
   params:[{id:'t',l:'θ',min:0,max:345,step:15,v:30,u:'°'}],
   draw:v=>{ const P=plane({x:[-1.5,1.5],y:[-1.5,1.5],step:.5,lab:1}); P.circ(0,0,1,{c:'var(--ink)',w:2});
     [1,2,3].forEach(k=>{ const a=rad(v.t*k); P.dot(Math.cos(a),Math.sin(a),{r:k===1?7:5,c:k===1?'var(--accent)':'var(--spark)',l:k===1?'z':k===2?'z²':'z³'}); }); P.dot(1,0,{r:4,c:'var(--ink)'}); return P.svg(); },
   ok:v=>v.t===120||v.t===240,why:'z³ = e^{3iθ} vaut 1 quand 3θ est un multiple de 360° : θ = 120° ou 240°. Avec 1, ces trois racines forment un triangle équilatéral.'},
  {kind:'Problème',h:'Construire un carré',
   p:'Dans le plan complexe, A = 1 + 2i et B = 4 + 3i sont deux sommets consécutifs d’un carré ABCD, parcouru dans le sens trigonométrique. Multiplier par i fait tourner de 90° : on s’en sert pour trouver C et D sans aucun dessin.',
   parts:[
    {q:'a) Combien vaut i(B − A) ?',opts:['3 + i','−1 + 3i','1 − 3i','−3 − i'],ans:1,hint:'B − A = 3 + i. Multiplie par i et utilise i² = −1.',why:'i(3 + i) = 3i + i² = −1 + 3i.'},
    {q:'b) C = B + i(B − A). Quelle est la partie imaginaire de C ?',lab:'Im(C) =',ans:6,hint:'Ajoute −1 + 3i à 4 + 3i.',why:'C = 4 + 3i − 1 + 3i = 3 + 6i.'},
    {q:'c) Quelle est l’aire du carré ?',ans:10,hint:'L’aire vaut |B − A|².',why:'|3 + i|² = 9 + 1 = 10.'},
   ],
   sol:'Le côté AB correspond à B − A = 3 + i. Tourner de 90° dans le sens trigonométrique, c’est multiplier par i : i(3 + i) = −1 + 3i.<br>D = A + i(B − A) = 1 + 2i − 1 + 3i = 5i et C = B + i(B − A) = 3 + 6i.<br>Aire : |B − A|² = 10.<br>Contrôle : le centre (A + C)/2 = 2 + 4i est aussi (B + D)/2.'},
  {kind:'Problème',h:'Les racines cubiques de 8i',
   p:'On résout <i>z³ = 8i</i> dans ℂ. On écrit 8i sous forme exponentielle, on en déduit les trois racines, puis on étudie leur somme, leur produit et le triangle qu’elles forment.',
   params:[{id:'k',l:'Racine k',min:0,max:2,v:0}],
   draw:v=>{ const P=plane({x:[-2.6,2.6],y:[-2.6,2.6],step:1,lab:1}); P.circ(0,0,2,{c:'var(--muted)',w:1.5}); const z=[30,150,270].map(t=>[2*Math.cos(rad(t)),2*Math.sin(rad(t))]); P.poly(z,{fill:'var(--accent)',fo:.15,c:'var(--accent)',w:2}); z.forEach((p,i)=>P.dot(p[0],p[1],{r:i===v.k?7:4,c:i===v.k?'var(--spark)':'var(--ink)'})); return P.svg(); },
   info:v=>`z<sub>${v.k}</sub> = 2·e<sup>i·${[30,150,270][v.k]}°</sup>`,
   parts:[
    {q:'a) Quel est le module commun des trois racines ?',ans:2,hint:'|z|³ = |8i| = 8.',why:'|z| = ∛8 = 2.'},
    {q:'b) Quel est le plus petit argument positif d’une racine ? (en degrés)',unit:'°',ans:30,hint:'8i = 8e^{i·90°}. Les arguments sont 90°/3 + k·120°.',why:'90° ÷ 3 = 30°. Les trois racines ont pour arguments 30°, 150° et 270°.'},
    {q:'c) Pourquoi la somme des trois racines est-elle nulle ?',opts:['Parce que 8i est imaginaire pur','Parce que z³ − 8i n’a pas de terme en z², et ce coefficient vaut −(z₀ + z₁ + z₂)','Parce que les racines sont toutes de module 2','Parce que l’une des racines vaut −2i'],ans:1,hint:'Développe (z − z₀)(z − z₁)(z − z₂).',why:'Le coefficient de z² vaut −(z₀ + z₁ + z₂). Il est nul dans z³ − 8i. On peut aussi dire que les racines forment un triangle équilatéral centré en 0.'},
    {q:'d) Quelle est l’aire du triangle formé par les trois racines ? (au centième)',ans:5.2,tol:.011,hint:'Un triangle équilatéral inscrit dans un cercle de rayon R a pour aire (3√3/4)·R².',why:'(3√3/4) · 4 = 3√3 ≈ 5,20.'},
   ],
   sol:'8i = 8e^{iπ/2}. Si z = re^{iθ}, alors r³ = 8 et 3θ = π/2 + 2kπ.<br>Donc r = 2 et θ = π/6 + 2kπ/3 : les racines sont 2e^{iπ/6} = √3 + i, 2e^{i5π/6} = −√3 + i et 2e^{i3π/2} = −2i.<br>Leur somme est nulle : (√3 + i) + (−√3 + i) + (−2i) = 0, comme le prévoit le coefficient de z².<br>Elles forment un triangle équilatéral inscrit dans le cercle de rayon 2 : aire 3√3 ≈ 5,20.'},
 ]},

{id:'alglin',br:'alg',lv:'uni',h:'Algèbre linéaire',p:'Vecteurs, combinaisons, matrices et déterminants.',
 lessons:['Combinaisons linéaires','Indépendance et bases','Matrices et systèmes','Le déterminant'],
 steps:[
  {h:'Combiner deux vecteurs',p:'Avec <b>u = (2 ; 1)</b> et <b>v = (−1 ; 2)</b>, la combinaison <i>αu + βv</i> peut atteindre n’importe quel point du plan.',
   params:[{id:'a',l:'α',min:-2,max:3,step:.5,v:1},{id:'b',l:'β',min:-2,max:3,step:.5,v:1}],
   draw:v=>{ const P=plane({x:[-5,6],y:[-4,7],lab:2}), ax=2*v.a, ay=v.a; P.arrow(0,0,ax,ay,{c:'var(--math)'}).arrow(ax,ay,ax-v.b,ay+2*v.b,{c:'var(--spark)'}).arrow(0,0,ax-v.b,ay+2*v.b,{w:4}); return P.svg(); },
   info:v=>`${fmt(v.a)}·u + ${fmt(v.b)}·v = (${fmt(2*v.a-v.b)} ; ${fmt(v.a+2*v.b)})`},
  {h:'Atteins la cible',p:'Trouve α et β pour que <i>αu + βv</i> arrive sur le point (3 ; 4).',
   params:[{id:'a',l:'α',min:-2,max:3,step:.5,v:0},{id:'b',l:'β',min:-2,max:3,step:.5,v:0}],
   draw:v=>{ const P=plane({x:[-5,6],y:[-4,7],lab:2}), ax=2*v.a, ay=v.a; P.dot(3,4,{c:'var(--bad)',l:'(3 ; 4)'}).arrow(0,0,ax,ay,{c:'var(--math)'}).arrow(ax,ay,ax-v.b,ay+2*v.b,{c:'var(--spark)'}); return P.svg(); },
   ok:v=>v.a===2&&v.b===1,why:'On résout 2α − β = 3 et α + 2β = 4 : α = 2, β = 1.'},
  {h:'Indépendance',p:'Les vecteurs (1 ; 2) et (2 ; 4) forment-ils une base du plan&nbsp;?',opts:['Oui','Non, ils sont colinéaires'],ans:1,why:'(2 ; 4) = 2·(1 ; 2). Leurs combinaisons restent sur une seule droite.'},
  {kind:'Défi',h:'Déterminant',p:`Calcule le déterminant de ${mat([[3,1],[2,4]])}.`,lab:'det =',ans:10,why:'det = ad − bc = 3·4 − 1·2 = 10.'},
  {kind:'Problème',h:'Un système par les déterminants',
   p:`On résout le système <i>2x + y = 5</i> et <i>x − 3y = −1</i> en l’écrivant <i>AX = B</i> avec A = ${mat([[2,1],[1,-3]].map(r=>r.map(fmt)))}. On utilise ensuite les déterminants pour savoir quand un tel système a une solution unique.`,
   parts:[
    {q:'a) Combien vaut det A ?',lab:'det =',ans:-7,hint:'det = ad − bc.',why:'2 · (−3) − 1 · 1 = −7.'},
    {q:'b) Avec la règle de Cramer, combien vaut x ?',lab:'x =',ans:2,hint:'Remplace la 1re colonne de A par (5 ; −1) et divise son déterminant par det A.',why:'x = (5 · (−3) − 1 · (−1)) ÷ (−7) = −14 ÷ (−7) = 2.'},
    {q:'c) Combien vaut y ?',lab:'y =',ans:1,hint:'Remplace la 2e colonne cette fois.',why:'y = (2 · (−1) − 5 · 1) ÷ (−7) = −7 ÷ (−7) = 1.'},
    {q:'d) Pour quelle valeur de k le système 2x + y = 5, x + ky = −1 n’a-t-il pas de solution unique ?',lab:'k =',ans:.5,tol:.001,hint:'Pas de solution unique quand le déterminant est nul.',why:'det = 2k − 1 = 0 pour k = ½.'},
   ],
   sol:'det A = −7 ≠ 0 : solution unique.<br>Cramer : x = det[[5, 1], [−1, −3]] / det A = −14/−7 = 2 et y = det[[2, 5], [1, −1]] / det A = −7/−7 = 1.<br>Contrôle : 4 + 1 = 5 et 2 − 3 = −1.<br>Avec x + ky = −1, det = 2k − 1. Pour k = ½, les deux lignes de la matrice sont proportionnelles : les droites sont parallèles. Ici elles sont distinctes (la 2e équation multipliée par 2 donne 2x + y = −2, incompatible avec 2x + y = 5) : il n’y a aucune solution.'},
  {kind:'Problème',h:'Trois vecteurs, une base ?',
   p:'Dans ℝ³, on considère <b>u</b> = (1 ; 1 ; 0), <b>v</b> = (0 ; 1 ; 1) et <b>w</b> = (1 ; 0 ; k), où k est un réel. On cherche pour quelles valeurs de k ces trois vecteurs forment une base, et ce qui se passe sinon.',
   parts:[
    {q:'a) Combien vaut le déterminant de (u, v, w) pour k = 2 ?',lab:'det =',ans:3,hint:'Développe selon la première ligne de la matrice dont les lignes sont u, v, w. Tu trouves une expression en k.',why:'det = 1·(1·k − 1·0) − 1·(0·k − 1·1) + 0 = k + 1. Pour k = 2 : 3.'},
    {q:'b) Pour quelle valeur de k les vecteurs sont-ils liés ?',lab:'k =',ans:-1,hint:'Ils sont liés si et seulement si le déterminant est nul.',why:'k + 1 = 0 donne k = −1.'},
    {q:'c) Pour k = −1, on écrit w = αu + βv. Combien vaut β ?',lab:'β =',ans:-1,hint:'Compare les composantes : la 1re donne α, la 3e donne β.',why:'(1 ; 0 ; −1) = α(1 ; 1 ; 0) + β(0 ; 1 ; 1) : α = 1, β = −1, et la 2e composante vérifie 1 − 1 = 0.'},
    {q:'d) Pour k ≠ −1, que peut-on conclure ?',opts:['u, v, w sont orthogonaux','u, v, w forment une base de ℝ³','w est combinaison de u et v','u, v, w engendrent un plan'],ans:1,hint:'Trois vecteurs de ℝ³ avec un déterminant non nul…',why:'det ≠ 0 : les trois vecteurs sont linéairement indépendants. Trois vecteurs indépendants de ℝ³ forment une base.'},
   ],
   sol:'det(u, v, w) = k + 1 (développement selon la 1re ligne).<br>Si k ≠ −1, le déterminant est non nul : les vecteurs sont indépendants, donc une base de ℝ³.<br>Si k = −1 : w = u − v, car (1 ; 1 ; 0) − (0 ; 1 ; 1) = (1 ; 0 ; −1).<br>Les trois vecteurs sont alors dans le plan engendré par u et v, et n’engendrent pas ℝ³.'},
 ]},

{id:'propres',br:'alg',lv:'uni',h:'Valeurs propres',p:'Les directions qu’une matrice ne fait pas tourner.',
 lessons:['Vecteurs propres','Polynôme caractéristique','Diagonalisation','Matrices symétriques'],
 steps:[
  {h:'Une direction qui résiste',p:`La matrice A = ${mat([[2,1],[1,2]])} transforme le vecteur bleu <b>v</b> en <b>Av</b> (jaune). En général, Av pointe ailleurs. Un <b>vecteur propre</b> garde sa direction : <i>Av = λv</i>.`,
   params:[{id:'t',l:'Direction de v',min:0,max:345,step:15,v:0,u:'°'}],
   draw:v=>{ const x=Math.cos(rad(v.t))*1.4,y=Math.sin(rad(v.t))*1.4,P=plane({x:[-5,5],y:[-5,5],lab:2}); P.arrow(0,0,2*x+y,x+2*y,{c:'var(--spark)',w:4}).arrow(0,0,x,y,{c:'var(--math)'}); return P.svg(); },
   info:v=>{ const t=rad(v.t),x=Math.cos(t),y=Math.sin(t),ax=2*x+y,ay=x+2*y,cr=Math.abs(x*ay-y*ax)<1e-9; return cr?`<b>Direction propre !</b> λ = ${fmt((ax*x+ay*y))}`:'Av n’est pas aligné avec v'; }},
  {h:'Trouve une direction propre',p:'Tourne <b>v</b> jusqu’à ce que <b>Av</b> soit sur la même droite.',
   params:[{id:'t',l:'Direction de v',min:0,max:345,step:15,v:15,u:'°'}],
   draw:v=>{ const x=Math.cos(rad(v.t))*1.4,y=Math.sin(rad(v.t))*1.4,P=plane({x:[-5,5],y:[-5,5],lab:2}); P.arrow(0,0,2*x+y,x+2*y,{c:'var(--spark)',w:4}).arrow(0,0,x,y,{c:'var(--math)'}); return P.svg(); },
   ok:v=>v.t%90===45,why:'Les directions propres sont 45° (λ = 3) et 135° (λ = 1), et leurs opposées.'},
  {h:'Lis la valeur propre',p:'Pour v = (1 ; 1), on trouve Av = (3 ; 3). Quelle est la valeur propre associée&nbsp;?',opts:['1','2','3','6'],ans:2,why:'Av = 3·v, donc λ = 3.'},
  {kind:'Défi',h:'Trace',p:`La somme des valeurs propres d’une matrice égale sa trace (somme de la diagonale). Pour ${mat([[4,1],[2,3]])}, combien vaut cette somme&nbsp;?`,ans:7,why:'Trace = 4 + 3 = 7. (Les valeurs propres sont 5 et 2.)'},
  {kind:'Problème',h:'Diagonaliser une matrice',
   p:`On étudie A = ${mat([[5,-2],[1,2]].map(r=>r.map(fmt)))}. On cherche ses valeurs propres à partir de la trace et du déterminant, puis un vecteur propre pour la plus grande.`,
   parts:[
    {q:'a) Combien vaut la trace de A ?',ans:7,hint:'Somme des coefficients diagonaux.',why:'5 + 2 = 7.'},
    {q:'b) Combien vaut det A ?',ans:12,hint:'ad − bc.',why:'5 · 2 − (−2) · 1 = 12.'},
    {q:'c) Quelle est la plus grande valeur propre ?',lab:'λ =',ans:4,hint:'Le polynôme caractéristique est λ² − (trace)·λ + det.',why:'λ² − 7λ + 12 = (λ − 3)(λ − 4). Les valeurs propres sont 3 et 4.'},
    {q:'d) Un vecteur propre pour λ = 4 s’écrit (2 ; y). Combien vaut y ?',lab:'y =',ans:1,hint:'Résous (A − 4I)v = 0.',why:`A − 4I = ${mat([[1,'−2'],[1,'−2']])} : il faut x − 2y = 0, donc (2 ; 1).`},
   ],
   sol:`Polynôme caractéristique : λ² − tr(A)λ + det A = λ² − 7λ + 12 = (λ − 3)(λ − 4).<br>Pour λ = 4 : A − 4I donne x − 2y = 0, d’où v₁ = (2 ; 1). Contrôle : A·(2 ; 1) = (8 ; 4).<br>Pour λ = 3 : A − 3I donne 2x − 2y = 0, d’où v₂ = (1 ; 1).<br>Avec P = ${mat([[2,1],[1,1]])}, on a A = PDP⁻¹ et D = diag(4, 3).`},
  {kind:'Problème',h:'Ville et campagne à long terme',
   p:`Chaque année, 10 % des citadins partent à la campagne et 20 % des campagnards s’installent en ville. Si (c ; r) donne les proportions en ville et à la campagne, l’année suivante vaut M·(c ; r) avec M = ${mat([['0,9','0,2'],['0,1','0,8']])}. Au départ, la population est répartie moitié-moitié.`,
   parts:[
    {q:'a) Pourquoi 1 est-il forcément valeur propre de M ?',opts:['Parce que la trace vaut 1,7','Parce que chaque colonne a une somme de 1, donc (1 ; 1) est vecteur propre de la transposée','Parce que M est symétrique','Parce que det M = 1'],ans:1,hint:'M et sa transposée ont les mêmes valeurs propres.',why:'Les colonnes somment à 1, donc Mᵀ(1 ; 1) = (1 ; 1). Mᵀ et M ont le même polynôme caractéristique. (Ici det M = 0,7.)'},
    {q:'b) Quelle est l’autre valeur propre ?',lab:'λ =',ans:.7,tol:.001,hint:'La somme des valeurs propres égale la trace.',why:'1,7 − 1 = 0,7.'},
    {q:'c) Vers quelle proportion de citadins la population tend-elle ? (fraction ou décimale)',ans:2/3,tol:.005,hint:'Cherche le vecteur propre de λ = 1 dont les composantes somment à 1.',why:'(M − I)v = 0 donne −0,1c + 0,2r = 0, soit c = 2r. Avec c + r = 1 : c = 2/3.'},
    {q:'d) L’écart à l’équilibre est multiplié par 0,7 chaque année. Après combien d’années la part des citadins dépasse-t-elle 65 % ?',unit:'ans',ans:7,hint:'Écart initial : 2/3 − 1/2 = 1/6. Il faut 1/6 · 0,7ⁿ < 2/3 − 0,65.',why:'0,7ⁿ < 0,1, donc n > ln 0,1 / ln 0,7 ≈ 6,46. Après 7 ans (65,3 %).'},
   ],
   sol:'Les colonnes de M somment à 1, donc 1 est valeur propre. La trace 1,7 donne l’autre : 0,7.<br>Équilibre : Mv = v donne c = 2r, donc (2/3 ; 1/3).<br>On décompose (½ ; ½) = (2/3 ; 1/3) + (1/6)(−1 ; 1), où (−1 ; 1) est propre pour 0,7.<br>Après n ans : c = 2/3 − (1/6)·0,7ⁿ. On veut (1/6)·0,7ⁿ < 1/60, soit 0,7ⁿ < 0,1 et n ≥ 7.<br>Contrôle : 0,55 ; 0,585 ; … ; c₆ ≈ 0,647 ; c₇ ≈ 0,653.'},
 ]},

{id:'limites',br:'ana',lv:'uni',h:'Limites et continuité',p:'La définition ε–δ, enfin rendue visible.',
 lessons:['Le jeu ε–δ','Limites remarquables','Continuité','Valeurs intermédiaires'],
 steps:[
  {h:'Le jeu ε–δ',p:'« lim f(x) = L quand x → a » veut dire : pour toute tolérance ε autour de L, on trouve une marge δ autour de a telle que f(x) reste dans la bande. Ici f(x) = 2x + 1, a = 1, L = 3.',
   params:[{id:'e',l:'ε',min:.1,max:1,step:.1,v:.6},{id:'d',l:'δ',min:.05,max:1,step:.05,v:.5}],
   draw:v=>{ const f=x=>2*x+1,P=plane({x:[-1,3],y:[0,6],h:300,lab:1}), ok=2*v.d<=v.e+1e-9;
     P.rect(-1,3-v.e,4,2*v.e,{fill:'var(--spark)',fo:.25,c:null}).rect(1-v.d,0,2*v.d,6,{fill:'var(--math)',fo:.15,c:null});
     P.fn(f,{c:'var(--muted)',w:2}).fn(f,{from:1-v.d,to:1+v.d,c:ok?'var(--ok)':'var(--bad)',w:5}).dot(1,3,{c:'var(--ink)',r:4}); return P.svg(); },
   info:v=>2*v.d<=v.e+1e-9?'Gagné : sur toute la marge δ, f(x) reste dans la bande ε.':'Perdu : le morceau rouge sort de la bande. Réduis δ.'},
  {h:'Trouve un δ',p:'Avec ε = 0,5, règle δ pour que la courbe reste dans la bande.',
   params:[{id:'d',l:'δ',min:.05,max:1,step:.05,v:.6}],
   draw:v=>{ const f=x=>2*x+1,e=.5,P=plane({x:[-1,3],y:[0,6],h:300,lab:1}), ok=2*v.d<=e+1e-9;
     P.rect(-1,3-e,4,2*e,{fill:'var(--spark)',fo:.25,c:null}).rect(1-v.d,0,2*v.d,6,{fill:'var(--math)',fo:.15,c:null}).fn(f,{c:'var(--muted)',w:2}).fn(f,{from:1-v.d,to:1+v.d,c:'var(--accent)',w:5}); return P.svg(); },
   ok:v=>v.d<=.25+1e-9,why:'|f(x) − 3| = 2|x − 1|. Il faut 2δ ≤ ε, donc δ ≤ ε/2 = 0,25. Ce raisonnement marche pour tout ε : la limite est prouvée.'},
  {h:'Une limite célèbre',p:'Combien vaut la limite de <i>sin(x)/x</i> quand x → 0&nbsp;?',
   fig:(()=>{ const P=plane({x:[-10,10],y:[-0.5,1.3],h:160,grid:false,lx:5,ly:1}); P.fn(x=>Math.abs(x)<1e-6?1:Math.sin(x)/x,{n:400}); return P.svg(); })(),
   opts:['0','1','+∞','Elle n’existe pas'],ans:1,why:'Près de 0, sin x ≈ x. Le quotient tend vers 1, même si la fonction n’est pas définie en 0.'},
  {kind:'Défi',h:'Valeurs intermédiaires',p:'f est continue sur [0 ; 2], f(0) = −1 et f(2) = 3. Que peut-on affirmer à coup sûr&nbsp;?',
   opts:['f s’annule au moins une fois entre 0 et 2','f est croissante','f(1) = 1','f s’annule exactement une fois'],ans:0,
   why:'Une fonction continue ne saute pas de valeurs : pour passer de −1 à 3, elle prend la valeur 0 au moins une fois. Rien n’empêche qu’elle le fasse plusieurs fois.'},
  {kind:'Problème',h:'Boucher les trous',
   p:'Certaines fonctions ne sont pas définies en un point, mais on peut parfois les prolonger par continuité en choisissant bien la valeur manquante. On étudie <i>f(x) = sin(3x)/x</i> en 0, <i>g(x) = (x² − 4)/(x − 2)</i> en 2 et <i>h(x) = |x|/x</i> en 0.',
   parts:[
    {q:'a) Combien vaut la limite de sin(3x)/x quand x → 0 ?',ans:3,hint:'Écris sin(3x)/x = 3 · sin(3x)/(3x).',why:'sin(3x)/(3x) → 1 quand x → 0, donc la limite vaut 3.'},
    {q:'b) Quelle valeur g(2) faut-il choisir pour que g soit continue en 2 ?',lab:'g(2) =',ans:4,hint:'Factorise x² − 4.',why:'(x² − 4)/(x − 2) = x + 2 pour x ≠ 2, qui tend vers 4.'},
    {q:'c) Peut-on prolonger h(x) = |x|/x par continuité en 0 ?',opts:['Oui, avec h(0) = 0','Oui, avec h(0) = 1','Non : la limite à gauche vaut −1 et à droite 1','Non, car h n’est pas définie en 0'],ans:2,hint:'Regarde séparément x > 0 et x < 0.',why:'h vaut 1 pour x > 0 et −1 pour x < 0. Les limites à gauche et à droite diffèrent : pas de limite, donc pas de prolongement.'},
   ],
   sol:'f : sin(3x)/x = 3 · sin(3x)/(3x) → 3 · 1 = 3. On prolonge par f(0) = 3.<br>g : pour x ≠ 2, g(x) = (x − 2)(x + 2)/(x − 2) = x + 2 → 4. On prolonge par g(2) = 4.<br>h : h(x) = 1 si x > 0 et −1 si x < 0. Les limites à gauche (−1) et à droite (1) diffèrent.<br>Un prolongement par continuité exige une limite : h ne peut pas être prolongée.<br>Ne pas être défini en un point ne dit rien à lui seul : tout dépend de la limite.'},
  {kind:'Problème',h:'Prouver que x² tend vers 9',
   p:'On veut prouver avec la définition ε–δ que <i>x² → 9</i> quand <i>x → 3</i>. On écrit |x² − 9| = |x − 3| · |x + 3|. Le facteur |x − 3| est petit, mais |x + 3| dépend de x : il faut le borner.',
   params:[{id:'e',l:'ε',min:.5,max:3,step:.5,v:2},{id:'d',l:'δ',min:.05,max:1,step:.05,v:.6}],
   draw:v=>{ const P=plane({x:[1,5],y:[0,18],w:300,h:240,grid:false,lx:1,ly:3}), ok=v.d*(6+v.d)<=v.e+1e-9;
     P.rect(1,9-v.e,4,2*v.e,{fill:'var(--spark)',fo:.25,c:null}).rect(3-v.d,0,2*v.d,18,{fill:'var(--math)',fo:.15,c:null}).fn(x=>x*x,{c:'var(--muted)',w:2}).fn(x=>x*x,{from:3-v.d,to:3+v.d,c:ok?'var(--ok)':'var(--bad)',w:5}).dot(3,9,{c:'var(--ink)',r:4}); return P.svg(); },
   info:v=>`sur la marge, |x² − 9| ≤ ${fmt(v.d*(6+v.d),3)} : ${v.d*(6+v.d)<=v.e+1e-9?'dans la bande ε':'sort de la bande ε'}`,
   parts:[
    {q:'a) Si |x − 3| ≤ 1, quelle est la plus grande valeur possible de |x + 3| ?',ans:7,hint:'Alors x est entre 2 et 4.',why:'x ∈ [2 ; 4], donc x + 3 ∈ [5 ; 7] et |x + 3| ≤ 7.'},
    {q:'b) On choisit δ = min(1 ; ε/7). Pour ε = 0,7, combien vaut δ ?',lab:'δ =',ans:.1,tol:.001,hint:'Compare 1 et 0,7/7.',why:'min(1 ; 0,1) = 0,1. Alors |x² − 9| ≤ 7 · 0,1 = 0,7.'},
    {q:'c) Pourquoi le min avec 1 est-il nécessaire ?',opts:['Pour que δ soit positif','Pour que la borne |x + 3| ≤ 7 soit valable','Parce que ε est toujours plus petit que 1','Il n’est pas nécessaire, δ = ε/7 suffit toujours'],ans:1,hint:'Essaie ε = 70 avec δ = ε/7 = 10.',why:'La borne |x + 3| ≤ 7 n’est vraie que si |x − 3| ≤ 1. Avec ε = 70 et δ = 10, x = 13 donne |x² − 9| = 160 > 70.'},
    {q:'d) Pour ε = 14, combien vaut δ = min(1 ; ε/7) ?',lab:'δ =',ans:1,tol:.001,hint:'Compare 1 et 14/7.',why:'min(1 ; 2) = 1. Et en effet |x − 3| ≤ 1 donne |x² − 9| ≤ 7 ≤ 14.'},
   ],
   sol:'Soit ε > 0. On pose δ = min(1 ; ε/7).<br>Si |x − 3| < δ, alors |x − 3| < 1, donc 2 < x < 4 et |x + 3| < 7.<br>D’où |x² − 9| = |x − 3| · |x + 3| < (ε/7) · 7 = ε.<br>Comme ε est quelconque, lim x² = 9 quand x → 3.<br>Le « 1 » est arbitraire : il sert seulement à borner le facteur |x + 3|. Tout autre choix fixe marcherait, avec une autre constante.'},
 ]},

{id:'series',br:'ana',lv:'uni',h:'Séries et Taylor',p:'Approcher les fonctions par des polynômes.',
 lessons:['Polynômes de Taylor','Séries géométriques','Critères de convergence','Rayon de convergence'],
 steps:[
  {h:'Imiter sin x avec un polynôme',p:'Le polynôme de Taylor reproduit la fonction près de 0. Plus son degré est élevé, plus il colle longtemps à la courbe.',
   params:[{id:'n',l:'Degré',min:1,max:13,step:2,v:1}],
   draw:v=>{ const T=x=>{ let s=0,t=x; for(let k=1;k<=v.n;k+=2){ s+=t; t*=-x*x/((k+1)*(k+2)); } return s; };
     const P=plane({x:[-7,7],y:[-3,3],h:200,grid:false,lx:2,ly:1}); P.fn(Math.sin,{c:'var(--muted)',w:5,op:.6}).fn(T,{n:400}); return P.svg(); },
   info:v=>{ const t=['x']; for(let k=3;k<=v.n;k+=2) t.push(`${k%4===3?'−':'+'} x${['','','','³','','⁵','','⁷','','⁹','','¹¹','','¹³'][k]}/${k}!`); return t.join(' '); }},
  {h:'Série géométrique',p:'Combien vaut 1 + ½ + ¼ + ⅛ + …&nbsp;?',ans:2,why:'Σ qⁿ = 1/(1 − q) pour |q| < 1. Avec q = ½ : 1/(1 − ½) = 2.'},
  {h:'Taylor de eˣ',p:'Le développement de <i>eˣ</i> en 0 à l’ordre 2 est…',opts:['1 + x + x²','1 + x + x²/2','x + x²/2','1 + 2x'],ans:1,why:'Toutes les dérivées de eˣ valent 1 en 0, donc eˣ ≈ 1 + x + x²/2! .'},
  {kind:'Défi',h:'La série harmonique',p:'1 + ½ + ⅓ + ¼ + …',opts:['converge vers 2','converge vers ln 2','diverge','converge vers π²/6'],ans:2,why:'Elle grandit sans limite, très lentement (comme ln n). C’est Σ 1/n² qui vaut π²/6.'},
  {kind:'Problème',h:'Une série et sa dérivée',
   p:'On pose <i>f(x) = Σₙ₌₀^∞ (x/3)ⁿ</i>. C’est une série géométrique. On cherche où elle converge, sa somme, puis on la dérive terme à terme pour calculer une autre somme.',
   parts:[
    {q:'a) Quel est le rayon de convergence de cette série ?',lab:'R =',ans:3,hint:'Une série géométrique converge si et seulement si |raison| < 1.',why:'|x/3| < 1 ⟺ |x| < 3. Le rayon vaut 3.'},
    {q:'b) Combien vaut f(1) ?',ans:1.5,tol:.001,hint:'Σ qⁿ = 1/(1 − q).',why:'1/(1 − 1/3) = 3/2.'},
    {q:'c) Que se passe-t-il en x = −3 ?',opts:['La série vaut 1/2','La série vaut 0','La série diverge : ses termes (−1)ⁿ ne tendent pas vers 0','La série converge, car |x| = R'],ans:2,hint:'Regarde le terme général.',why:'Le terme général (−1)ⁿ ne tend pas vers 0 : condition nécessaire violée, la série diverge.'},
    {q:'d) En dérivant f terme à terme, calcule Σₙ₌₁^∞ n/3ⁿ.',ans:.75,tol:.001,hint:'f(x) = 3/(3 − x) et f′(x) = Σ n xⁿ⁻¹/3ⁿ. Évalue en x = 1.',why:'f′(x) = 3/(3 − x)², donc f′(1) = 3/4 = Σ n/3ⁿ.'},
   ],
   sol:'f(x) = Σ (x/3)ⁿ converge si |x| < 3, et vaut 1/(1 − x/3) = 3/(3 − x).<br>f(1) = 3/2. En x = ±3, le terme général ne tend pas vers 0 : divergence.<br>Une série entière se dérive terme à terme dans son disque de convergence : f′(x) = Σₙ≥₁ n xⁿ⁻¹/3ⁿ = 3/(3 − x)².<br>En x = 1 : Σ n/3ⁿ = 3/4.'},
  {kind:'Problème',h:'L’intégrale de la cloche',
   p:'L’intégrale <i>I = ∫₀¹ e^{−x²} dx</i> n’a pas de primitive élémentaire. On remplace e^{−x²} par sa série de Taylor, on intègre terme à terme et on contrôle l’erreur avec le critère des séries alternées.',
   parts:[
    {q:'a) Quelle est la série de e^{−x²} ?',opts:['Σ x²ⁿ/n!','Σ (−1)ⁿ x²ⁿ/n!','Σ (−1)ⁿ x²ⁿ/(2n)!','Σ (−1)ⁿ xⁿ/n!'],ans:1,hint:'Remplace u par −x² dans eᵘ = Σ uⁿ/n!.',why:'(−x²)ⁿ = (−1)ⁿ x²ⁿ, donc e^{−x²} = Σ (−1)ⁿ x²ⁿ/n!.'},
    {q:'b) En intégrant de 0 à 1, I = Σ (−1)ⁿ/((2n + 1)·n!). Que vaut la somme des 4 premiers termes (n = 0 à 3) ? (4 décimales)',ans:.7429,tol:.0002,hint:'1 − 1/3 + 1/10 − 1/42.',why:'1 − 0,3333 + 0,1 − 0,0238 ≈ 0,7429.'},
    {q:'c) Que garantit le critère des séries alternées sur cette approximation ?',opts:['L’erreur est inférieure au premier terme omis, 1/216 ≈ 0,0046','L’erreur est nulle','L’erreur est inférieure au dernier terme gardé, 1/42','On ne peut rien dire sans calculer I'],ans:0,hint:'Les termes décroissent et tendent vers 0, avec des signes alternés.',why:'Pour une série alternée à termes décroissants vers 0, l’erreur est majorée par la valeur absolue du premier terme omis : 1/(9 · 24) = 1/216.'},
    {q:'d) Combien de termes faut-il garder pour que ce critère garantisse une erreur inférieure à 10⁻⁴ ?',unit:'termes',ans:7,hint:'Calcule 1/((2n + 1)·n!) pour n = 5, 6, 7.',why:'n = 6 : 1/9360 ≈ 1,07·10⁻⁴, encore trop grand. n = 7 : 1/75 600 ≈ 1,3·10⁻⁵. Le premier terme omis doit être n = 7 : on garde n = 0 à 6, soit 7 termes.'},
   ],
   sol:'e^{−x²} = Σ (−1)ⁿ x²ⁿ/n!, série qui converge uniformément sur [0 ; 1] : on peut intégrer terme à terme.<br>I = Σ (−1)ⁿ / ((2n + 1) n!) = 1 − 1/3 + 1/10 − 1/42 + 1/216 − …<br>Avec 4 termes : 0,7429, à moins de 1/216 ≈ 0,0046 près.<br>Pour garantir 10⁻⁴, le premier terme omis doit être < 10⁻⁴ : c’est le terme n = 7 (≈ 1,3·10⁻⁵). On garde 7 termes et I ≈ 0,74684.'},
 ]},

{id:'edo',br:'ana',lv:'uni',h:'Équations différentielles',p:'Quand le taux de variation dépend de l’état.',
 lessons:['Croissance et décroissance','Équations linéaires d’ordre 1','L’oscillateur harmonique','Champs de directions'],
 steps:[
  {h:'Suivre les petites flèches',p:'L’équation <i>y′ = k·y</i> dit en chaque point dans quelle direction partir. La solution qui passe par y(0) = y₀ est <i>y₀·e^{kx}</i>.',
   params:[{id:'k',l:'k',min:-1,max:1,step:.1,v:.5},{id:'y',l:'y₀',min:-2,max:2,step:.5,v:1}],
   draw:v=>{ const P=plane({x:[-3,3],y:[-3,3],lab:1});
     for(let x=-2.5;x<=2.5;x+=.5) for(let y=-2.5;y<=2.5;y+=.5){ const m=v.k*y,L=.18/Math.hypot(1,m); P.seg(x-L,y-L*m,x+L,y+L*m,{c:'var(--muted)',w:1.5}); }
     P.fn(x=>v.y*Math.exp(v.k*x),{c:'var(--accent)',w:3.5}).dot(0,v.y,{r:5}); return P.svg(); },
   info:v=>`y = ${fmt(v.y)}·e^(${fmt(v.k)}x)`},
  {h:'Reconnaître la solution',p:'Les solutions de <i>y′ = 3y</i> sont…',opts:['y = 3x + C','y = C·e^{3x}','y = e^{x/3}','y = C·x³'],ans:1,why:'(C·e^{3x})′ = 3·C·e^{3x} = 3y.'},
  {h:'Demi-vie',p:'Un échantillon radioactif de 80 g a une demi-vie de 5 ans. Combien en reste-t-il après 15 ans&nbsp;?',unit:'g',ans:10,why:'15 ans font 3 demi-vies : 80 → 40 → 20 → 10 g.'},
  {kind:'Défi',h:'Le ressort',p:'Quelles fonctions vérifient <i>y″ = −y</i>&nbsp;?',opts:['eˣ et e⁻ˣ','sin x et cos x','x² et x','ln x'],ans:1,why:'(sin x)″ = −sin x et (cos x)″ = −cos x. C’est l’équation d’un ressort sans frottement.'},
  {kind:'Problème',h:'Le café qui refroidit',
   p:'Un café à 90 °C est posé dans une pièce à 20 °C. Selon la loi de Newton, sa température vérifie <i>T′ = −k(T − 20)</i>. Après 10 minutes, il est à 60 °C. On veut savoir quand il sera à 30 °C.',
   parts:[
    {q:'a) La solution est T(t) = 20 + 70e^{−kt}. Combien vaut k ? (en min⁻¹, 3 décimales)',lab:'k =',ans:.056,tol:.0006,hint:'T(10) = 60 donne e^{−10k} = 40/70.',why:'k = ln(70/40)/10 = ln(1,75)/10 ≈ 0,056.'},
    {q:'b) Quelle est la température après 20 minutes ? (au centième)',unit:'°C',ans:42.86,tol:.011,hint:'e^{−20k} = (e^{−10k})² = (4/7)².',why:'20 + 70 · 16/49 = 20 + 160/7 ≈ 42,86 °C.'},
    {q:'c) Quand le café atteint-il 30 °C ? (au dixième de minute)',unit:'min',ans:34.8,tol:.051,hint:'Résous 70e^{−kt} = 10.',why:'t = ln 7 / k = 10 ln 7 / ln 1,75 ≈ 34,8 min.'},
    {q:'d) Vers quoi tend T(t) quand t → +∞ ?',opts:['0 °C','20 °C','60 °C','−∞'],ans:1,hint:'Que devient e^{−kt} avec k > 0 ?',why:'e^{−kt} → 0, donc T → 20 °C : le café prend la température de la pièce.'},
   ],
   sol:'On pose u = T − 20. Alors u′ = −ku, donc u = u₀e^{−kt} avec u₀ = 70.<br>T(10) = 60 donne e^{−10k} = 4/7, soit k = ln(7/4)/10 ≈ 0,056 min⁻¹.<br>T(20) = 20 + 70 · (4/7)² ≈ 42,86 °C.<br>T = 30 ⟺ e^{−kt} = 1/7 ⟺ t = 10 ln 7 / ln(7/4) ≈ 34,8 min.<br>À long terme, T → 20 °C.'},
  {kind:'Problème',h:'Un ressort lancé',
   p:'Une masse au bout d’un ressort vérifie <i>y″ + 4y = 0</i>. Au départ, elle est à la position y(0) = 1 et on la lance avec la vitesse y′(0) = 2. On veut l’amplitude, la période et le premier passage par la position d’équilibre.',
   params:[{id:'t',l:'Temps t',min:0,max:6.25,step:.25,v:0}],
   draw:v=>{ const y=t=>Math.cos(2*t)+Math.sin(2*t), P=plane({x:[-0.3,6.6],y:[-1.8,1.8],w:320,h:180,grid:false,lx:1,ly:1}); P.fn(y,{from:0,to:6.5}).seg(v.t,-1.8,v.t,1.8,{c:'var(--muted)',w:1,dash:true}).dot(v.t,y(v.t)); return P.svg(); },
   info:v=>`y(${fmt(v.t)}) ≈ ${fmt(Math.cos(2*v.t)+Math.sin(2*v.t),3)}`,
   parts:[
    {q:'a) Quelle est la forme générale des solutions ?',opts:['A e^{2t} + B e^{−2t}','A cos 2t + B sin 2t','A cos 4t + B sin 4t','(A + Bt) e^{2t}'],ans:1,hint:'L’équation caractéristique r² + 4 = 0 a pour racines ±2i.',why:'r = ±2i donne des oscillations de pulsation 2 : y = A cos 2t + B sin 2t.'},
    {q:'b) Avec les conditions initiales, combien vaut B ?',lab:'B =',ans:1,hint:'y(0) = A et y′(0) = 2B.',why:'A = 1 et 2B = 2, donc B = 1 : y = cos 2t + sin 2t.'},
    {q:'c) Quelle est l’amplitude du mouvement ? (au centième)',ans:1.41,tol:.011,hint:'A cos ωt + B sin ωt = √(A² + B²) · sin(ωt + φ).',why:'√(1 + 1) = √2 ≈ 1,41.'},
    {q:'d) À quel instant t > 0 la masse passe-t-elle pour la première fois par y = 0 ? (au centième)',lab:'t =',unit:'s',ans:1.18,tol:.011,hint:'cos 2t + sin 2t = √2 sin(2t + π/4).',why:'2t + π/4 = π donne t = 3π/8 ≈ 1,18 s.'},
   ],
   sol:'Équation caractéristique : r² + 4 = 0, r = ±2i. Donc y = A cos 2t + B sin 2t.<br>y(0) = A = 1 et y′(0) = 2B = 2, d’où y = cos 2t + sin 2t.<br>On écrit y = √2 sin(2t + π/4) : amplitude √2 ≈ 1,41, période 2π/2 = π ≈ 3,14 s.<br>Premier zéro : 2t + π/4 = π, soit t = 3π/8 ≈ 1,18 s.<br>Lancer la masse augmente l’amplitude : sans vitesse initiale, elle serait de 1.'},
 ]},

{id:'transfo',br:'geo',lv:'uni',h:'Transformations linéaires',p:'Les matrices comme déformations du plan.',
 lessons:['Matrices qui déforment le plan','Rotations et symétries','Déterminant et aire','Composer des transformations'],
 steps:[
  {h:'Une matrice déforme la grille',p:'Les colonnes de la matrice sont les images de <b>e₁</b> (bleu) et <b>e₂</b> (jaune). Toute la grille suit. Le carré unité devient un parallélogramme.',
   params:[{id:'a',l:'a',min:-2,max:2,step:.5,v:1},{id:'b',l:'b',min:-2,max:2,step:.5,v:.5},{id:'c',l:'c',min:-2,max:2,step:.5,v:0},{id:'d',l:'d',min:-2,max:2,step:.5,v:1}],
   draw:v=>{ const P=plane({x:[-4,4],y:[-4,4],grid:false}), T=(x,y)=>[v.a*x+v.b*y,v.c*x+v.d*y];
     for(let i=-3;i<=3;i++){ const p=T(i,-3),q=T(i,3),r=T(-3,i),s=T(3,i); P.seg(p[0],p[1],q[0],q[1],{c:'var(--line)',w:1.2}).seg(r[0],r[1],s[0],s[1],{c:'var(--line)',w:1.2}); }
     P.poly([[0,0],T(1,0),T(1,1),T(0,1)],{fill:'var(--accent)',fo:.3,c:'var(--accent)',w:2}).arrow(0,0,v.a,v.c,{c:'var(--math)'}).arrow(0,0,v.b,v.d,{c:'var(--spark)'}); return P.svg(); },
   info:v=>`${mat([[fmt(v.a),fmt(v.b)],[fmt(v.c),fmt(v.d)]])} &nbsp; det = ad − bc = ${fmt(v.a*v.d-v.b*v.c)}`},
  {h:'Fabrique une rotation',p:'Règle la matrice pour qu’elle fasse tourner le plan de 90° dans le sens inverse des aiguilles d’une montre.',
   params:[{id:'a',l:'a',min:-1,max:1,v:1},{id:'b',l:'b',min:-1,max:1,v:0},{id:'c',l:'c',min:-1,max:1,v:0},{id:'d',l:'d',min:-1,max:1,v:1}],
   draw:v=>{ const P=plane({x:[-2.5,2.5],y:[-2.5,2.5],step:.5,lab:1}); P.poly([[0,0],[v.a,v.c],[v.a+v.b,v.c+v.d],[v.b,v.d]],{fill:'var(--accent)',fo:.3,c:'var(--accent)',w:2}).arrow(0,0,v.a,v.c,{c:'var(--math)'}).arrow(0,0,v.b,v.d,{c:'var(--spark)'}).dot(0,1,{r:4,c:'var(--muted)'}).dot(-1,0,{r:4,c:'var(--muted)'}); return P.svg(); },
   info:v=>mat([[v.a,v.b],[v.c,v.d]]),ok:v=>v.a===0&&v.b===-1&&v.c===1&&v.d===0,why:'e₁ = (1 ; 0) doit aller sur (0 ; 1), et e₂ = (0 ; 1) sur (−1 ; 0). Ce sont les deux colonnes.'},
  {h:'Symétrie',p:'Le déterminant d’une symétrie axiale vaut…',opts:['1','−1','0','2'],ans:1,why:'Elle conserve les aires (|det| = 1) mais inverse l’orientation (signe −).'},
  {kind:'Défi',h:'Aire de l’image',p:`Quelle est l’aire de l’image du carré unité par ${mat([[2,1],[0,3]])}&nbsp;?`,ans:6,why:'L’aire est multipliée par |det| = |2·3 − 1·0| = 6.'},
  {kind:'Problème',h:'Le cisaillement',
   p:`La matrice C = ${mat([[1,2],[0,1]])} fait « glisser » le plan horizontalement : chaque point est poussé vers la droite d’autant plus qu’il est haut. On étudie l’image du carré unité, l’aire, et ce que donne C appliquée deux fois.`,
   params:[{id:'k',l:'Fraction de la transformation',min:0,max:1,step:.25,v:1}],
   draw:v=>{ const s=2*v.k, P=plane({x:[-0.5,4],y:[-0.5,2],w:300,lab:1}); P.rect(0,0,1,1,{c:'var(--muted)',w:1.5,dash:true}).poly([[0,0],[1,0],[1+s,1],[s,1]],{fill:'var(--accent)',fo:.3,c:'var(--accent)',w:2}).dot(1+s,1,{l:'image de (1 ; 1)',r:4}); return P.svg(); },
   parts:[
    {q:'a) Quelle est l’abscisse de l’image du point (1 ; 1) ?',lab:'x =',ans:3,hint:'Multiplie C par le vecteur (1 ; 1).',why:'C·(1 ; 1) = (1 + 2 ; 1) = (3 ; 1).'},
    {q:'b) Quelle est l’aire de l’image d’un triangle d’aire 4 ?',ans:4,hint:'L’aire est multipliée par |det C|.',why:'det C = 1 · 1 − 2 · 0 = 1 : les aires sont conservées.'},
    {q:'c) C² = C·C est encore un cisaillement. Quel est son coefficient en haut à droite ?',ans:4,hint:'Calcule le produit, ou pense à ce que fait C appliquée deux fois.',why:`C² = ${mat([[1,4],[0,1]])} : deux glissements de 2 font un glissement de 4.`},
   ],
   sol:`C·(1 ; 0) = (1 ; 0) et C·(0 ; 1) = (2 ; 1) : le carré unité devient le parallélogramme (0 ; 0), (1 ; 0), (3 ; 1), (2 ; 1).<br>det C = 1 : même base 1, même hauteur 1, donc même aire. Toute aire est conservée.<br>C² = ${mat([[1,4],[0,1]])} et plus généralement Cⁿ = ${mat([[1,'2n'],[0,1]])}.<br>L’inverse est le cisaillement de coefficient −2.`},
  {kind:'Problème',h:'Rotation puis symétrie',
   p:`On note R la rotation de 90° (sens trigonométrique) et S la symétrie par rapport à l’axe des x : R = ${mat([[0,'−1'],[1,0]])} et S = ${mat([[1,0],[0,'−1']])}. On étudie la composée S∘R (d’abord R, puis S), qui s’écrit SR, et on la compare à R∘S.`,
   parts:[
    {q:'a) Combien vaut det(SR) ?',lab:'det =',ans:-1,hint:'det(SR) = det S · det R.',why:'(−1) · 1 = −1 : SR renverse l’orientation et conserve les aires.'},
    {q:'b) Quelle est l’ordonnée de l’image du point (2 ; 5) par S∘R ?',lab:'y =',ans:-2,hint:'Applique d’abord R, puis S.',why:'R(2 ; 5) = (−5 ; 2), puis S(−5 ; 2) = (−5 ; −2).'},
    {q:'c) Quelle est la nature de S∘R ?',opts:['Une rotation de −90°','La symétrie par rapport à la droite y = x','La symétrie par rapport à la droite y = −x','Une rotation de 180°'],ans:2,hint:`Calcule SR = ${mat([[0,'−1'],['−1',0]])} et cherche les vecteurs fixes.`,why:'SR envoie (x ; y) sur (−y ; −x). Les points de y = −x sont fixes et det = −1 : c’est la symétrie d’axe y = −x.'},
    {q:'d) Et R∘S ?',opts:['C’est la même transformation','C’est la symétrie par rapport à y = x','C’est la rotation de 90°','C’est l’identité'],ans:1,hint:'Calcule RS.',why:`RS = ${mat([[0,1],[1,0]])} échange x et y : symétrie d’axe y = x. Donc RS ≠ SR : la composition n’est pas commutative.`},
   ],
   sol:`SR = ${mat([[1,0],[0,'−1']])}${mat([[0,'−1'],[1,0]])} = ${mat([[0,'−1'],['−1',0]])}, soit (x ; y) ↦ (−y ; −x).<br>det(SR) = −1 et (SR)² = I : c’est une symétrie axiale. Son axe est formé des points fixes : y = −x.<br>RS = ${mat([[0,1],[1,0]])}, soit (x ; y) ↦ (y ; x) : la symétrie d’axe y = x.<br>Les deux composées sont des symétries, mais d’axes différents : l’ordre compte.`},
 ]},

{id:'parametrees',br:'geo',lv:'uni',h:'Courbes paramétrées',p:'Dessiner en fonction du temps, des Lissajous aux spirales.',
 lessons:['Tracer en fonction du temps','Vitesse et tangente','Coordonnées polaires','Longueur d’arc'],
 steps:[
  {h:'Les figures de Lissajous',p:'Un point se déplace avec <i>x(t) = sin(a·t + π/2)</i> et <i>y(t) = sin(b·t)</i>. Le rapport a/b décide de la forme.',
   params:[{id:'a',l:'a',min:1,max:5,v:3},{id:'b',l:'b',min:1,max:5,v:2}],
   draw:v=>{ const P=plane({x:[-1.3,1.3],y:[-1.3,1.3],step:.5,lab:1}); P.curve(t=>Math.sin(v.a*t+Math.PI/2),t=>Math.sin(v.b*t),0,2*Math.PI,{n:600}); return P.svg(); },
   info:v=>`a/b = ${v.a}/${v.b}`},
  {h:'Reconnais la courbe',p:'<i>x = cos t</i>, <i>y = sin t</i> pour t de 0 à 2π décrit…',opts:['une droite','le cercle unité','une parabole','une spirale'],ans:1,why:'cos² t + sin² t = 1 : chaque point est à distance 1 de l’origine.'},
  {h:'En polaires',p:'En coordonnées polaires, la courbe <i>r = θ</i> (le rayon grandit avec l’angle) est…',opts:['un cercle','une droite','une spirale','une rose à 4 pétales'],ans:2,why:'À chaque tour, la distance au centre augmente de 2π : c’est la spirale d’Archimède.'},
  {kind:'Défi',h:'Longueur d’arc',p:'Quelle est la longueur de la courbe <i>x = 2 cos t</i>, <i>y = 2 sin t</i> pour t ∈ [0 ; 2π]&nbsp;? (arrondie au centième)',ans:12.57,tol:.011,why:'L = ∫ √(x′² + y′²) dt = ∫₀^{2π} 2 dt = 4π ≈ 12,57.'},
  {kind:'Problème',h:'Le tir au but',
   p:'Un ballon est frappé depuis le sol. Sa position (en m) après <i>t</i> secondes est <i>x(t) = 12t</i>, <i>y(t) = 16t − 5t²</i>. On cherche quand et où il retombe, sa hauteur maximale et sa vitesse au sommet.',
   params:[{id:'t',l:'Temps t',min:0,max:3.2,step:.2,v:.8}],
   draw:v=>{ const P=plane({x:[-2,42],y:[-2,16],w:320,grid:false,lx:10,ly:5}); P.curve(t=>12*t,t=>16*t-5*t*t,0,3.2,{c:'var(--muted)',w:2,dash:true}).arrow(12*v.t,16*v.t-5*v.t*v.t,12*v.t+12*.25,16*v.t-5*v.t*v.t+(16-10*v.t)*.25,{c:'var(--spark)',w:2.5}).dot(12*v.t,16*v.t-5*v.t*v.t); return P.svg(); },
   info:v=>`vitesse (${fmt(12)} ; ${fmt(16-10*v.t)}) · norme ${fmt(Math.hypot(12,16-10*v.t))} m/s`,
   parts:[
    {q:'a) À quel instant le ballon retombe-t-il au sol ?',lab:'t =',unit:'s',ans:3.2,tol:.001,hint:'Résous y(t) = 0 avec t > 0.',why:'t(16 − 5t) = 0 donne t = 16/5 = 3,2 s.'},
    {q:'b) À quelle distance retombe-t-il ?',unit:'m',ans:38.4,tol:.001,hint:'Calcule x(3,2).',why:'12 × 3,2 = 38,4 m.'},
    {q:'c) Quelle hauteur maximale atteint-il ?',unit:'m',ans:12.8,tol:.001,hint:'Au sommet, y′(t) = 0.',why:'y′(t) = 16 − 10t = 0 en t = 1,6 s, et y(1,6) = 25,6 − 12,8 = 12,8 m.'},
    {q:'d) Quelle est sa vitesse (norme) au sommet ?',unit:'m/s',ans:12,tol:.001,hint:'Le vecteur vitesse est (x′(t) ; y′(t)).',why:'Au sommet, (x′ ; y′) = (12 ; 0), de norme 12 m/s : seule la composante horizontale reste.'},
   ],
   sol:'y(t) = t(16 − 5t) = 0 pour t = 3,2 s, et x(3,2) = 38,4 m.<br>Vitesse : (x′ ; y′) = (12 ; 16 − 10t). Le sommet est atteint quand y′ = 0, en t = 1,6 s.<br>Hauteur maximale : y(1,6) = 12,8 m, à x = 19,2 m, au milieu de la portée.<br>Au sommet, la vitesse est horizontale : 12 m/s, la plus petite du vol.'},
  {kind:'Problème',h:'L’arche de la cycloïde',
   p:'Un point collé sur une roue de rayon 1 qui roule sans glisser décrit la <b>cycloïde</b> <i>x(t) = t − sin t</i>, <i>y(t) = 1 − cos t</i>. On étudie sa vitesse et la longueur d’une arche, pour t ∈ [0 ; 2π].',
   params:[{id:'t',l:'Paramètre t',min:0,max:6.25,step:.25,v:1.5}],
   draw:v=>{ const P=plane({x:[-0.5,7],y:[-0.5,2.8],w:320,grid:false,lx:1,ly:1}); P.curve(t=>t-Math.sin(t),t=>1-Math.cos(t),0,2*Math.PI,{c:'var(--muted)',w:2}).circ(v.t,1,1,{c:'var(--math)',w:1.5}).seg(v.t,1,v.t-Math.sin(v.t),1-Math.cos(v.t),{c:'var(--math)',w:1.5}).curve(t=>t-Math.sin(t),t=>1-Math.cos(t),0,v.t,{c:'var(--accent)',w:3.5}).dot(v.t-Math.sin(v.t),1-Math.cos(v.t)); return P.svg(); },
   info:v=>`longueur parcourue : ${fmt(4-4*Math.cos(v.t/2),3)} · vitesse ${fmt(2*Math.abs(Math.sin(v.t/2)),3)}`,
   parts:[
    {q:'a) Quelle est la vitesse (norme) du point en t = π ?',ans:2,tol:.001,hint:'Vitesse : (1 − cos t ; sin t). Calcule sa norme en π.',why:'(1 − cos π ; sin π) = (2 ; 0), de norme 2. Au sommet, le point va deux fois plus vite que le centre de la roue.'},
    {q:'b) Que se passe-t-il en t = 0 ?',opts:['La vitesse est maximale','La vitesse est nulle : la courbe a un point de rebroussement','La courbe a une tangente horizontale','La courbe n’est pas définie'],ans:1,hint:'Évalue le vecteur vitesse en 0.',why:'(1 − cos 0 ; sin 0) = (0 ; 0). Le point touche le sol et s’arrête un instant : la cycloïde forme une pointe.'},
    {q:'c) Quelle est la longueur d’une arche ?',ans:8,tol:.001,hint:'(1 − cos t)² + sin² t = 2 − 2cos t = 4 sin²(t/2).',why:'L = ∫₀^{2π} 2 sin(t/2) dt = [−4 cos(t/2)]₀^{2π} = 4 + 4 = 8.'},
   ],
   sol:'Vecteur vitesse : (1 − cos t ; sin t), de norme √(2 − 2 cos t) = 2|sin(t/2)|.<br>En t = 0 et t = 2π, la vitesse est nulle : la cycloïde a des points de rebroussement au contact du sol.<br>En t = π, la vitesse vaut 2, le maximum.<br>Longueur : sur [0 ; 2π], sin(t/2) ≥ 0, donc L = ∫₀^{2π} 2 sin(t/2) dt = 8.<br>Résultat remarquable : une arche mesure exactement 4 fois le diamètre de la roue, sans aucun π.'},
 ]},
];
